/**
 * スタンプ画像を透過PNGとして描画・生成するモジュール
 * Excelへの画像挿入（workbook.addImage）用
 */

export function renderStampToPng(stamp) {
  // ブラウザ環境でない場合はnull
  if (typeof document === 'undefined') return null;

  let width = Math.max(16, Math.round(stamp.width || 40));
  let height = Math.max(14, Math.round(stamp.height || 30));
  const rotation = stamp.rotation || 0;
  const color = stamp.color || '#2563eb';

  let effectiveFontSize = Math.max(10, Math.round(height * 0.55));

  // テキストスタンプの場合、エディタ編集時のサイズ（stamp.height）を忠実に反映し、
  // Excelタブ譜行（高さ18pt/約24px）と美しく調和するスケール（約0.8倍）で描画
  if (stamp.type === 'text') {
    const text = stamp.text || '注記';
    // エディタの1弦高さ30pxに対するExcelタブ譜行24pxの比率（0.8倍）
    const excelScale = 0.8;
    height = Math.max(12, Math.round((stamp.height || 26) * excelScale));
    effectiveFontSize = Math.max(8, Math.round(height * 0.55));
    const fontStr = `bold ${effectiveFontSize}px "Segoe UI", "Hiragino Sans", Meiryo, sans-serif`;

    const measureCanvas = document.createElement('canvas');
    const measureCtx = measureCanvas.getContext('2d');
    if (measureCtx) {
      measureCtx.font = fontStr;
      const textMetrics = measureCtx.measureText(text);
      // 文字長さに合わせて左右に適切な余白（各4px）を取った幅
      width = Math.ceil(textMetrics.width) + 8;
    }
  }

  // 回転によるバウンディングボックスの計算
  const rad = (rotation * Math.PI) / 180;
  const cos = Math.abs(Math.cos(rad));
  const sin = Math.abs(Math.sin(rad));
  const boundW = Math.max(12, Math.ceil(width * cos + height * sin));
  const boundH = Math.max(10, Math.ceil(width * sin + height * cos));

  // 高解像度（2倍スケール）で描画
  const scale = 2;
  const canvas = document.createElement('canvas');
  canvas.width = boundW * scale;
  canvas.height = boundH * scale;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.scale(scale, scale);

  // 中心に移動して回転
  ctx.translate(boundW / 2, boundH / 2);
  ctx.rotate(rad);
  ctx.translate(-width / 2, -height / 2);

  // スタンプの種類ごとに描画
  switch (stamp.type) {
    case 'choke':
      ctx.fillStyle = color || '#dc2626';
      ctx.font = `bold ${Math.round(height * 0.9)}px "Segoe UI", Arial, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('c', width / 2, height / 2);
      break;

    case 'line':
      ctx.strokeStyle = color || '#059669';
      ctx.lineWidth = Math.max(3, height * 0.25);
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(4, height / 2);
      ctx.lineTo(width - 4, height / 2);
      ctx.stroke();
      break;

    case 'tie':
      ctx.fillStyle = color || '#2563eb';
      ctx.beginPath();
      // 上向きの滑らかな弧線（タイ・スラー）
      ctx.moveTo(2, height * 0.8);
      ctx.quadraticCurveTo(width / 2, height * 0.05, width - 2, height * 0.8);
      ctx.quadraticCurveTo(width / 2, height * 0.35, 2, height * 0.8);
      ctx.closePath();
      ctx.fill();
      break;

    case 'wholeRest':
      ctx.fillStyle = color || '#d97706';
      ctx.fillRect(width * 0.15, height * 0.25, width * 0.7, height * 0.5);
      ctx.strokeStyle = color || '#d97706';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(2, height * 0.25);
      ctx.lineTo(width - 2, height * 0.25);
      ctx.stroke();
      break;

    case 'quarterRest':
      ctx.strokeStyle = color || '#d97706';
      ctx.fillStyle = color || '#d97706';
      ctx.lineWidth = Math.max(2.5, width * 0.1);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      // 4分休符シンボル
      ctx.moveTo(width * 0.6, height * 0.05);
      ctx.lineTo(width * 0.35, height * 0.32);
      ctx.lineTo(width * 0.65, height * 0.55);
      ctx.lineTo(width * 0.35, height * 0.75);
      ctx.quadraticCurveTo(width * 0.7, height * 0.85, width * 0.3, height * 0.95);
      ctx.stroke();
      break;

    case 'text':
    default:
      ctx.fillStyle = color || '#0f172a';
      ctx.font = `bold ${effectiveFontSize}px "Segoe UI", "Hiragino Sans", Meiryo, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(stamp.text || '注記', width / 2, height / 2);
      break;
  }

  const dataUrl = canvas.toDataURL('image/png');
  const base64 = dataUrl.replace(/^data:image\/png;base64,/, '');

  return {
    base64,
    width: boundW,
    height: boundH
  };
}
