/**
 * Web Audio API を用いたギター音プレビューエンジン
 */
import { STRINGS_CONFIG } from '../models/types.js';

export class PlaybackEngine {
  constructor() {
    this.audioCtx = null;
    this.isPlaying = false;
    this.timerId = null;
    this.currentMeasureIndex = 0;
    this.currentSlotIndex = 0;
    this.activeVoices = [];
    this.onTick = null; // コールバック: (measureId, slotIndex) => {}
    this.onStop = null; // コールバック: () => {}
  }

  initContext() {
    if (!this.audioCtx) {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      this.audioCtx = new AudioContext();

      // マスターコンプレッサー（同時発音時の音割れを防止し、音圧とクリアさを向上）
      this.compressor = this.audioCtx.createDynamicsCompressor();
      this.compressor.threshold.setValueAtTime(-18, this.audioCtx.currentTime);
      this.compressor.knee.setValueAtTime(12, this.audioCtx.currentTime);
      this.compressor.ratio.setValueAtTime(8, this.audioCtx.currentTime);
      this.compressor.attack.setValueAtTime(0.003, this.audioCtx.currentTime);
      this.compressor.release.setValueAtTime(0.2, this.audioCtx.currentTime);

      this.masterGain = this.audioCtx.createGain();
      this.masterGain.gain.setValueAtTime(0.85, this.audioCtx.currentTime);

      this.compressor.connect(this.masterGain);
      this.masterGain.connect(this.audioCtx.destination);
    }
    if (this.audioCtx.state === 'suspended') {
      this.audioCtx.resume();
    }
  }

  // MIDI番号から周波数（Hz）を計算
  midiToFreq(midi) {
    return 440 * Math.pow(2, (midi - 69) / 12);
  }

  // ギター風プラック音を再生（数字以外のテキストは無音）
  playGuitarPluck(stringIndex, fretNumber, duration = 0.8, offsetTime = 0) {
    if (!this.audioCtx) this.initContext();
    const ctx = this.audioCtx;

    // 【要件】数字以外のテキストの場所は無音にする
    if (fretNumber === undefined || fretNumber === null) return;
    const s = String(fretNumber).trim();
    if (!/^\d+$/.test(s)) {
      return; // 数字以外のテキスト（文字、記号、チョーキングc、ミュートx等）は無音
    }

    const fret = parseInt(s, 10);
    if (isNaN(fret) || fret < 0 || fret > 30) return;

    if (!STRINGS_CONFIG[stringIndex]) return;
    const baseMidi = STRINGS_CONFIG[stringIndex].openMidi;
    const noteMidi = baseMidi + fret;
    const freq = this.midiToFreq(noteMidi);

    const now = ctx.currentTime + Math.max(0, offsetTime);

    // オシレーター（複合波形でギターのアコースティック倍音をシミュレート）
    const osc1 = ctx.createOscillator();
    const osc2 = ctx.createOscillator();
    const gainNode = ctx.createGain();
    const filter = ctx.createBiquadFilter();

    osc1.type = 'triangle';
    osc1.frequency.setValueAtTime(freq, now);

    osc2.type = 'sawtooth';
    osc2.frequency.setValueAtTime(freq * 1.0025, now); // わずかなデチューンで弦の厚みを表現

    // ローパスフィルター（弾かれた瞬間のきらびやかさと自然な減衰）
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(freq * 5.5, now);
    filter.frequency.exponentialRampToValueAtTime(Math.max(80, freq * 1.2), now + Math.min(duration, 0.4));

    // 音量エンベロープ（瞬間的なアタックと減衰）
    gainNode.gain.setValueAtTime(0, now);
    gainNode.gain.linearRampToValueAtTime(0.2, now + 0.004);
    gainNode.gain.exponentialRampToValueAtTime(0.0005, now + duration);

    osc1.connect(filter);
    osc2.connect(filter);
    filter.connect(gainNode);

    if (this.compressor) {
      gainNode.connect(this.compressor);
    } else {
      gainNode.connect(ctx.destination);
    }

    osc1.start(now);
    osc2.start(now);
    osc1.stop(now + duration + 0.05);
    osc2.stop(now + duration + 0.05);

    if (!this.activeVoices) this.activeVoices = [];
    this.activeVoices.push(osc1, osc2);
    setTimeout(() => {
      if (this.activeVoices) {
        this.activeVoices = this.activeVoices.filter(v => v !== osc1 && v !== osc2);
      }
    }, (duration + 0.1) * 1000);
  }

  // 指定セクションの再生（セクション内の小節のみを順番に演奏し、完了時に自動停止）
  playSection(section, bpm = 120) {
    this.initContext();
    this.stop(false);
    this.isPlaying = true;

    const measures = section?.measures || [];
    if (measures.length === 0) {
      this.stop();
      return;
    }

    let measIdx = 0;
    let slotIdx = 0;

    const validBpm = (typeof bpm === 'number' && bpm > 0) ? bpm : (parseInt(bpm, 10) || 120);
    // 1小節 = 4拍 = (60 / bpm) * 4 秒
    const measureDurationSec = (60 / validBpm) * 4;

    const step = () => {
      if (!this.isPlaying) return;

      const currentMeasure = measures[measIdx];
      if (!currentMeasure) {
        this.stop();
        return;
      }

      const totalSlots = (currentMeasure.half1Divisions || 4) + (currentMeasure.half2Divisions || 4);
      const slotDurationSec = measureDurationSec / totalSlots;

      // 縦に同一で並んだ6弦をいっぺんに鳴らす（数字以外のテキストは無音）
      if (currentMeasure.notes) {
        const activeNotes = [];
        for (let strIdx = 5; strIdx >= 0; strIdx--) {
          const stringNotes = currentMeasure.notes[strIdx];
          if (stringNotes && stringNotes[slotIdx] !== undefined) {
            const rawVal = stringNotes[slotIdx];
            const s = String(rawVal).trim();
            if (/^\d+$/.test(s)) {
              activeNotes.push({ strIdx, val: s });
            }
          }
        }

        const noteDuration = Math.min(1.4, slotDurationSec * 2.2);
        activeNotes.forEach((item, noteIdx) => {
          const strokeOffset = activeNotes.length > 1 ? noteIdx * 0.003 : 0;
          this.playGuitarPluck(item.strIdx, item.val, noteDuration, strokeOffset);
        });
      }

      // UI通知（縦一列のハイライト更新）
      if (this.onTick) {
        this.onTick(currentMeasure.id, slotIdx);
      }

      slotIdx++;
      if (slotIdx >= totalSlots) {
        slotIdx = 0;
        measIdx++;
        if (measIdx >= measures.length) {
          // このセクションの演奏終了
          this.stop();
          return;
        }
      }

      this.timerId = setTimeout(step, slotDurationSec * 1000);
    };

    step();
  }

  // 全曲の再生（縦に同一で並んだ6弦をいっぺんに鳴らし、順番に右へと再生）
  playSong(song, startMeasureId = null) {
    this.initContext();
    this.stop(false);
    this.isPlaying = true;

    // 全セクションの小節を平坦化
    const allMeasures = [];
    song.sections.forEach(sec => {
      sec.measures.forEach(m => {
        allMeasures.push({ ...m, sectionColor: sec.color, sectionType: sec.type });
      });
    });

    if (allMeasures.length === 0) return;

    let startIndex = 0;
    if (startMeasureId) {
      const idx = allMeasures.findIndex(m => m.id === startMeasureId);
      if (idx !== -1) startIndex = idx;
    }

    let measIdx = startIndex;
    let slotIdx = 0;

    const validBpm = (typeof song.bpm === 'number' && song.bpm > 0) ? song.bpm : (parseInt(song.bpm, 10) || 120);
    // 1小節 = 4拍 = (60 / bpm) * 4 秒
    const measureDurationSec = (60 / validBpm) * 4;

    const step = () => {
      if (!this.isPlaying) return;

      const currentMeasure = allMeasures[measIdx];
      if (!currentMeasure) {
        this.stop();
        return;
      }

      const totalSlots = (currentMeasure.half1Divisions || 4) + (currentMeasure.half2Divisions || 4);
      const slotDurationSec = measureDurationSec / totalSlots;

      // 【要件】縦に同一で並んだ6弦をいっぺんに鳴らす（数字以外のテキストは無音）
      if (currentMeasure.notes) {
        const activeNotes = [];
        // 6弦(低音)から1弦(高音)まで同一スロットのノートを収集
        for (let strIdx = 5; strIdx >= 0; strIdx--) {
          const stringNotes = currentMeasure.notes[strIdx];
          if (stringNotes && stringNotes[slotIdx] !== undefined) {
            const rawVal = stringNotes[slotIdx];
            const s = String(rawVal).trim();
            // 数字のみ判定（数字以外のテキストは無音）
            if (/^\d+$/.test(s)) {
              activeNotes.push({ strIdx, val: s });
            }
          }
        }

        // 同一スロットに音がある場合、6弦をいっぺんに（極小ストロークディレイで自然なコード感）再生
        const noteDuration = Math.min(1.4, slotDurationSec * 2.2);
        activeNotes.forEach((item, noteIdx) => {
          // 和音の場合はごくわずかなオフセット（約0.003秒）で同時に響かせる
          const strokeOffset = activeNotes.length > 1 ? noteIdx * 0.003 : 0;
          this.playGuitarPluck(item.strIdx, item.val, noteDuration, strokeOffset);
        });
      }

      // UI通知（縦一列のハイライト更新）
      if (this.onTick) {
        this.onTick(currentMeasure.id, slotIdx);
      }

      slotIdx++;
      if (slotIdx >= totalSlots) {
        slotIdx = 0;
        measIdx++;
        if (measIdx >= allMeasures.length) {
          // 曲の終了
          this.stop();
          return;
        }
      }

      this.timerId = setTimeout(step, slotDurationSec * 1000);
    };

    step();
  }

  stop(triggerCallback = true) {
    this.isPlaying = false;
    if (this.timerId) {
      clearTimeout(this.timerId);
      this.timerId = null;
    }
    // 発音中の全オシレーターを即時停止・切断
    if (this.activeVoices && this.activeVoices.length > 0) {
      this.activeVoices.forEach(voice => {
        try {
          voice.stop();
          voice.disconnect();
        } catch (e) {}
      });
      this.activeVoices = [];
    }
    // マスターゲインを即座に消音して復帰
    if (this.audioCtx && this.masterGain) {
      try {
        const now = this.audioCtx.currentTime;
        this.masterGain.gain.cancelScheduledValues(now);
        this.masterGain.gain.setValueAtTime(0, now);
        this.masterGain.gain.setValueAtTime(0.85, now + 0.05);
      } catch (e) {}
    }
    if (triggerCallback && this.onStop) {
      this.onStop();
    }
  }
}
