/**
 * 小節ビュー (MeasureView)
 * 仕様：
 * - 6弦分のタブ
 * - タブは半小節ごとに好きな数で分割でき（デフォルト4, 最小1, 最大16）、フレット番号を入力できる
 * - １小節単位でカラーを変えられる
 * - タブの上にコード入力（自由な場所に直打ち入力）
 */
import { STRINGS_CONFIG, COLOR_PALETTE, generateId } from '../models/types.js';

export class MeasureView {
  constructor(app, measure, section) {
    this.app = app;
    this.measure = measure;
    this.section = section;
  }

  render() {
    const m = this.measure;
    const isChordOnly = Boolean(this.section && this.section.isChordOnly);
    const card = document.createElement('div');
    card.className = 'measure-card';
    if (isChordOnly) {
      card.classList.add('measure-chord-only');
    }
    card.id = `measure-${m.id}`;
    card.dataset.measureId = m.id;

    // 小節背景色
    if (m.color && m.color !== 'transparent') {
      card.style.backgroundColor = m.color;
    }

    // 小節ドラッグ受け入れ対応（ドロップ先としての設定）
    card.dataset.measureId = m.id;
    card.dataset.sectionId = this.section.id;

    card.addEventListener('dragover', (e) => {
      if (e.dataTransfer.types.includes('application/tabmaker-stamp')) {
        return;
      }
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      const rect = card.getBoundingClientRect();
      const midX = rect.left + rect.width / 2;
      if (e.clientX < midX) {
        card.classList.add('drag-over-before');
        card.classList.remove('drag-over-after');
      } else {
        card.classList.add('drag-over-after');
        card.classList.remove('drag-over-before');
      }
    });

    card.addEventListener('dragleave', (e) => {
      if (card.contains(e.relatedTarget)) return;
      card.classList.remove('drag-over-before', 'drag-over-after');
    });

    card.addEventListener('drop', (e) => {
      if (e.dataTransfer.types.includes('application/tabmaker-stamp')) {
        return;
      }
      card.classList.remove('drag-over-before', 'drag-over-after');
      try {
        const raw = e.dataTransfer.getData('text/plain');
        if (!raw) return;
        const data = JSON.parse(raw);
        if (data && data.type === 'tabmaker-measure') {
          e.preventDefault();
          e.stopPropagation();
          if (data.sourceSecId === this.section.id && data.sourceMeasId === m.id) {
            return; // 同一小節へのドロップは何もしない
          }
          const rect = card.getBoundingClientRect();
          const placeBefore = e.clientX < (rect.left + rect.width / 2);
          this.app.moveMeasure(data.sourceSecId, data.sourceMeasId, this.section.id, m.id, placeBefore);
        }
      } catch (err) {
        // 無視
      }
    });

    // 1. 上部コントロールバー（ドラッグハンドル、小節番号、半小節分割数、コピー、貼付、小節カラー、削除）
    const topBar = document.createElement('div');
    topBar.className = 'measure-top-bar';

    // 左側：ドラッグハンドル & 小節番号
    const leftInfo = document.createElement('div');
    leftInfo.className = 'measure-top-left';

    // 小節の移動は左上のマークでのみ行う
    const dragHandle = document.createElement('span');
    dragHandle.className = 'measure-drag-handle';
    dragHandle.innerHTML = '⠿';
    dragHandle.title = 'ドラッグして小節を並べ替え・移動';
    dragHandle.setAttribute('draggable', 'true');

    dragHandle.addEventListener('dragstart', (e) => {
      e.stopPropagation();
      e.dataTransfer.setData('text/plain', JSON.stringify({
        type: 'tabmaker-measure',
        sourceSecId: this.section.id,
        sourceMeasId: m.id
      }));
      e.dataTransfer.effectAllowed = 'move';
      card.classList.add('is-dragging-measure');

      // ドラッグ中のプレビューとして小節カード全体を表示
      if (e.dataTransfer.setDragImage) {
        const rect = card.getBoundingClientRect();
        e.dataTransfer.setDragImage(card, e.clientX - rect.left, e.clientY - rect.top);
      }
    });

    dragHandle.addEventListener('dragend', () => {
      card.classList.remove('is-dragging-measure');
      document.querySelectorAll('.measure-card').forEach(c => {
        c.classList.remove('drag-over-before', 'drag-over-after');
      });
    });

    // --- タッチ・ポインターによる小節ドラッグ操作（Android / モバイル対応） ---
    let touchDragging = false;
    let floatingPreview = null;
    let currentDropTarget = null;

    const updatePreviewPosition = (x, y) => {
      if (floatingPreview) {
        floatingPreview.style.left = `${x}px`;
        floatingPreview.style.top = `${y}px`;
      }
    };

    const checkDropTarget = (clientX, clientY) => {
      // 全カードのハイライトを一旦クリア
      document.querySelectorAll('.measure-card').forEach(c => {
        c.classList.remove('drag-over-before', 'drag-over-after');
      });

      // 指の下にある要素を取得
      const el = document.elementFromPoint(clientX, clientY);
      if (!el) {
        currentDropTarget = null;
        return;
      }

      const targetCard = el.closest('.measure-card');
      if (targetCard && targetCard.dataset.measureId && targetCard.dataset.measureId !== m.id) {
        const rect = targetCard.getBoundingClientRect();
        const placeBefore = clientX < (rect.left + rect.width / 2);
        targetCard.classList.add(placeBefore ? 'drag-over-before' : 'drag-over-after');
        currentDropTarget = {
          targetSecId: targetCard.dataset.sectionId,
          targetMeasId: targetCard.dataset.measureId,
          placeBefore: placeBefore
        };
      } else {
        currentDropTarget = null;
      }
    };

    const onPointerMove = (e) => {
      if (!touchDragging) return;
      if (e.cancelable) e.preventDefault();
      updatePreviewPosition(e.clientX, e.clientY);
      checkDropTarget(e.clientX, e.clientY);
    };

    const onTouchMove = (e) => {
      if (!touchDragging) return;
      if (e.cancelable) e.preventDefault();
      const touch = e.touches[0];
      if (touch) {
        updatePreviewPosition(touch.clientX, touch.clientY);
        checkDropTarget(touch.clientX, touch.clientY);
      }
    };

    const removeAllPreviews = () => {
      document.querySelectorAll('.drag-floating-preview').forEach(el => el.remove());
      floatingPreview = null;
    };

    const onPointerUp = () => {
      if (!touchDragging) {
        removeAllPreviews();
        return;
      }
      touchDragging = false;

      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('pointercancel', onPointerUp);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', onPointerUp);

      removeAllPreviews();

      card.classList.remove('is-dragging-measure');
      document.querySelectorAll('.measure-card').forEach(c => {
        c.classList.remove('drag-over-before', 'drag-over-after');
      });

      if (currentDropTarget) {
        const { targetSecId, targetMeasId, placeBefore } = currentDropTarget;
        this.app.moveMeasure(this.section.id, m.id, targetSecId, targetMeasId, placeBefore);
        currentDropTarget = null;
      }
    };

    const onPointerDown = (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      e.stopPropagation();

      // 他の画面上に残存するプレビューを一括消去
      removeAllPreviews();

      touchDragging = true;
      currentDropTarget = null;
      card.classList.add('is-dragging-measure');

      // フローティングプレビューバッジを画面上に生成
      floatingPreview = document.createElement('div');
      floatingPreview.className = 'drag-floating-preview';
      floatingPreview.innerHTML = `<span>⠿ 小節 #${m.number} を移動中</span>`;
      document.body.appendChild(floatingPreview);

      const clientX = e.clientX ?? (e.touches && e.touches[0] ? e.touches[0].clientX : 0);
      const clientY = e.clientY ?? (e.touches && e.touches[0] ? e.touches[0].clientY : 0);
      updatePreviewPosition(clientX, clientY);

      window.addEventListener('pointermove', onPointerMove, { passive: false });
      window.addEventListener('pointerup', onPointerUp);
      window.addEventListener('pointercancel', onPointerUp);
      window.addEventListener('touchmove', onTouchMove, { passive: false });
      window.addEventListener('touchend', onPointerUp);
    };

    dragHandle.addEventListener('pointerdown', onPointerDown);

    leftInfo.appendChild(dragHandle);

    const numTag = document.createElement('span');
    numTag.className = 'measure-number-tag';
    numTag.textContent = `#${m.number || 1}`;
    leftInfo.appendChild(numTag);

    topBar.appendChild(leftInfo);

    // 半小節分割コントローラー (前半・後半の分割数: 最小1, 最大16, デフォルト4)
    const divControls = document.createElement('div');
    divControls.className = 'division-controls';

    // 前半
    divControls.appendChild(this.createDivisionBox('前半', m.half1Divisions || 4, (val) => {
      this.updateHalfDivisions(val, m.half2Divisions || 4);
      this.app.saveStateAndRender();
    }));

    // 後半
    divControls.appendChild(this.createDivisionBox('後半', m.half2Divisions || 4, (val) => {
      this.updateHalfDivisions(m.half1Divisions || 4, val);
      this.app.saveStateAndRender();
    }));

    topBar.appendChild(divControls);

    // 小節アクション（コピー、貼付、カラー変更、小節削除）
    const actions = document.createElement('div');
    actions.className = 'measure-actions';

    // 小節コピーボタン
    const copyBtn = document.createElement('button');
    copyBtn.className = 'btn-mini-action btn-mini-copy';
    copyBtn.innerHTML = '📋';
    copyBtn.title = 'この小節をコピー';
    copyBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.app.copyMeasure(m);
    });
    actions.appendChild(copyBtn);

    // 小節貼付ボタン（この小節の直後に挿入）
    const pasteBtn = document.createElement('button');
    pasteBtn.className = `btn-mini-action btn-mini-paste ${this.app.clipboardMeasure ? 'has-clipboard' : ''}`;
    pasteBtn.innerHTML = '📥';
    pasteBtn.title = this.app.clipboardMeasure
      ? `コピーした小節をこの直後に貼り付け`
      : '小節をコピーするとこの後ろに貼り付けできます';
    pasteBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.app.pasteMeasure(this.section.id, m.id);
    });
    actions.appendChild(pasteBtn);

    // カラーピッカーボタン
    const colorBtn = document.createElement('button');
    colorBtn.className = 'btn-mini-color';
    colorBtn.style.backgroundColor = m.color && m.color !== 'transparent' ? m.color : '#334155';
    colorBtn.title = '小節のカラーを変更（薄いパステルカラー）';
    colorBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.app.showColorPicker(colorBtn, (selectedColor) => {
        m.color = selectedColor;
        this.app.saveStateAndRender();
      }, 'measure');
    });
    actions.appendChild(colorBtn);

    // 小節削除ボタン
    const delBtn = document.createElement('button');
    delBtn.className = 'btn-mini-del';
    delBtn.innerHTML = '🗑️';
    delBtn.title = 'この小節を削除';
    delBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (confirm(`小節 #${m.number} を削除しますか？`)) {
        this.section.measures = this.section.measures.filter(item => item.id !== m.id);
        this.app.renumberMeasures();
        this.app.saveStateAndRender();
      }
    });
    actions.appendChild(delBtn);

    topBar.appendChild(actions);
    if (!isChordOnly) {
      card.appendChild(topBar);
    }

    // 2. コードトラック (Chord Bar: タブの上にコード直打ち入力)
    const chordTrack = document.createElement('div');
    chordTrack.className = 'chord-track-container';
    chordTrack.title = 'クリックした場所にコードを入力';

    if (!m.chords || m.chords.length === 0) {
      const ph = document.createElement('div');
      ph.className = 'chord-track-placeholder';
      ph.textContent = '+ コードを入力';
      chordTrack.appendChild(ph);
    } else {
      m.chords.forEach(chord => {
        const tag = document.createElement('div');
        tag.className = 'chord-tag';
        tag.style.left = `${chord.positionPercent}%`;
        tag.title = 'タップしてコード修正 / ドラッグして移動';
        tag.innerHTML = `<span class="chord-name">${chord.text}</span>`;

        // コードテキストの編集モーダル呼び出し
        const openEditModal = () => {
          this.app.openChordEditModal({
            title: '🎵 コードの編集',
            currentText: chord.text,
            showDelete: true,
            onSave: (newText) => {
              chord.text = newText;
              this.app.saveStateAndRender();
            },
            onDelete: () => {
              m.chords = m.chords.filter(c => c.id !== chord.id);
              this.app.saveStateAndRender();
            }
          });
        };

        // 位置のドラッグ移動とタップ（クリック）によるテキスト編集
        let isDraggingChord = false;
        let isPointerMoved = false;
        let startX = 0;
        let startY = 0;
        let startPercent = chord.positionPercent;

        const onChordPointerDown = (e) => {
          if (e.button !== undefined && e.button !== 0) return;
          e.stopPropagation();

          isDraggingChord = false;
          isPointerMoved = false;
          startX = e.clientX ?? (e.touches && e.touches[0] ? e.touches[0].clientX : 0);
          startY = e.clientY ?? (e.touches && e.touches[0] ? e.touches[0].clientY : 0);
          startPercent = chord.positionPercent;

          const onChordPointerMove = (moveEvent) => {
            const currentX = moveEvent.clientX ?? (moveEvent.touches && moveEvent.touches[0] ? moveEvent.touches[0].clientX : startX);
            const currentY = moveEvent.clientY ?? (moveEvent.touches && moveEvent.touches[0] ? moveEvent.touches[0].clientY : startY);
            const dist = Math.hypot(currentX - startX, currentY - startY);

            if (dist > 6) {
              isPointerMoved = true;
              isDraggingChord = true;
              if (moveEvent.cancelable) moveEvent.preventDefault();

              const trackRect = chordTrack.getBoundingClientRect();
              const deltaX = currentX - startX;
              const deltaPercent = (deltaX / trackRect.width) * 100;
              let newPercent = Math.max(0, Math.min(95, Math.round(startPercent + deltaPercent)));
              chord.positionPercent = newPercent;
              tag.style.left = `${newPercent}%`;
            }
          };

          const onChordPointerUp = () => {
            window.removeEventListener('pointermove', onChordPointerMove);
            window.removeEventListener('pointerup', onChordPointerUp);
            window.removeEventListener('pointercancel', onChordPointerUp);
            window.removeEventListener('touchmove', onChordPointerMove);
            window.removeEventListener('touchend', onChordPointerUp);

            if (isDraggingChord) {
              isDraggingChord = false;
              this.app.saveState();
              this.app.pushHistory();
            } else if (!isPointerMoved) {
              // 指・マウスを動かさずに離した（＝タップまたはクリック！）
              openEditModal();
            }
          };

          window.addEventListener('pointermove', onChordPointerMove, { passive: false });
          window.addEventListener('pointerup', onChordPointerUp);
          window.addEventListener('pointercancel', onChordPointerUp);
          window.addEventListener('touchmove', onChordPointerMove, { passive: false });
          window.addEventListener('touchend', onChordPointerUp);
        };

        tag.addEventListener('pointerdown', onChordPointerDown);

        chordTrack.appendChild(tag);
      });
    }

    // コードトラックをクリックして新規コード追加モーダルを開く
    chordTrack.addEventListener('click', (e) => {
      if (e.target.closest('.chord-tag')) return;
      const rect = chordTrack.getBoundingClientRect();
      const clickX = e.clientX - rect.left;
      const percent = Math.max(0, Math.min(95, Math.round((clickX / rect.width) * 100)));

      this.app.openChordEditModal({
        title: '➕ コードの新規追加',
        currentText: 'C',
        showDelete: false,
        onSave: (newText) => {
          if (!m.chords) m.chords = [];
          m.chords.push({
            id: generateId('ch'),
            text: newText,
            positionPercent: percent
          });
          this.app.saveStateAndRender();
        }
      });
    });

    card.appendChild(chordTrack);

    // コードセクション（コード入力の行のみ）の場合は6弦TAB譜面を描画せず返す
    if (isChordOnly) {
      const hoverActions = document.createElement('div');
      hoverActions.className = 'chord-only-measure-actions';

      const copyMiniBtn = document.createElement('button');
      copyMiniBtn.type = 'button';
      copyMiniBtn.className = 'btn-mini-action';
      copyMiniBtn.innerHTML = '📋';
      copyMiniBtn.title = 'この小節をコピー';
      copyMiniBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this.app.copyMeasure(m);
      });
      hoverActions.appendChild(copyMiniBtn);

      const delMiniBtn = document.createElement('button');
      delMiniBtn.type = 'button';
      delMiniBtn.className = 'btn-mini-del';
      delMiniBtn.innerHTML = '🗑️';
      delMiniBtn.title = 'この小節を削除';
      delMiniBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (confirm(`小節 #${m.number} を削除しますか？`)) {
          this.section.measures = this.section.measures.filter(item => item.id !== m.id);
          this.app.renumberMeasures();
          this.app.saveStateAndRender();
        }
      });
      hoverActions.appendChild(delMiniBtn);

      chordTrack.appendChild(hoverActions);
      return card;
    }

    // 3. 6弦分のTAB譜面エリア（小節ごとの一番前のセクション指定カラー線を廃止）
    const tabWrapper = document.createElement('div');
    tabWrapper.className = 'tab-notation-wrapper';

    // クリックでスタンプ配置チェック（クリック選択モード）
    tabWrapper.addEventListener('click', (e) => {
      if (this.app.stampManager.activeStampType) {
        const rect = tabWrapper.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        this.app.stampManager.addStampToMeasure(m, x, y, rect.width, rect.height);
      }
    });

    // スタンプ一覧からのドラッグ＆ドロップ配置
    tabWrapper.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'copy';
      tabWrapper.classList.add('stamp-drop-target');
    });

    tabWrapper.addEventListener('dragleave', (e) => {
      tabWrapper.classList.remove('stamp-drop-target');
    });

    tabWrapper.addEventListener('drop', (e) => {
      e.preventDefault();
      tabWrapper.classList.remove('stamp-drop-target');
      const stampType = e.dataTransfer.getData('application/tabmaker-stamp');
      if (stampType) {
        const rect = tabWrapper.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        this.app.stampManager.addStampToMeasureWithType(m, stampType, x, y, rect.width, rect.height);
      }
    });

    const stringRows = document.createElement('div');
    stringRows.className = 'tab-string-rows';

    const half1 = m.half1Divisions || 4;
    const half2 = m.half2Divisions || 4;
    const totalSlots = half1 + half2;

    // 分割数合計に応じたクラス付与（16以下は1小節幅に圧縮表示、17以上は2倍幅・2小節/1行）
    card.dataset.totalSlots = totalSlots;
    if (totalSlots >= 17) {
      card.classList.add('measure-wide');
      if (totalSlots >= 25) {
        card.classList.add('measure-very-dense');
      }
    } else if (totalSlots >= 12) {
      card.classList.add('measure-dense');
    }

    // 6本の弦をレンダリング（0: 1弦E, 1: 2弦B, 2: 3弦G, 3: 4弦D, 4: 5弦A, 5: 6弦E）
    for (let strIdx = 0; strIdx < 6; strIdx++) {
      const row = document.createElement('div');
      row.className = 'tab-string-row';
      row.dataset.stringIndex = strIdx;

      // スロットコンテナ
      const slotsContainer = document.createElement('div');
      slotsContainer.className = 'tab-slots-container';

      // 前半グループ（前半の入力数に応じた比率で幅を割り当て、最大16まで小節内に均等表示）
      const half1Group = document.createElement('div');
      half1Group.className = 'half-measure-group half-1';
      half1Group.style.flex = `${half1} 1 0%`;
      for (let slot = 0; slot < half1; slot++) {
        half1Group.appendChild(this.createSlotCell(m, strIdx, slot, totalSlots));
      }
      slotsContainer.appendChild(half1Group);

      // 後半グループ（後半の入力数に応じた比率で幅を割り当て）
      const half2Group = document.createElement('div');
      half2Group.className = 'half-measure-group half-2';
      half2Group.style.flex = `${half2} 1 0%`;
      for (let slot = half1; slot < totalSlots; slot++) {
        half2Group.appendChild(this.createSlotCell(m, strIdx, slot, totalSlots));
      }
      slotsContainer.appendChild(half2Group);

      row.appendChild(slotsContainer);
      stringRows.appendChild(row);
    }

    tabWrapper.appendChild(stringRows);

    // 4. スタンプオーバーレイレイヤー
    const stampOverlay = document.createElement('div');
    stampOverlay.className = 'stamp-overlay-layer';
    stampOverlay.id = `stamp-overlay-${m.id}`;
    this.app.stampManager.renderStampsForMeasure(m, stampOverlay);
    tabWrapper.appendChild(stampOverlay);

    card.appendChild(tabWrapper);
    return card;
  }

  // 前半と後半を完全に独立させたまま分割数を変更する
  updateHalfDivisions(newHalf1, newHalf2) {
    const m = this.measure;
    const oldHalf1 = m.half1Divisions || 4;
    const oldHalf2 = m.half2Divisions || 4;

    if (m.notes) {
      for (let strIdx = 0; strIdx < 6; strIdx++) {
        const oldRow = m.notes[strIdx] || {};
        const newRow = {};

        // 1. 前半の音符を独立して保持 (0 .. newHalf1 - 1)
        const keepHalf1 = Math.min(oldHalf1, newHalf1);
        for (let i = 0; i < keepHalf1; i++) {
          if (oldRow[i] !== undefined && oldRow[i] !== '') {
            newRow[i] = oldRow[i];
          }
        }

        // 2. 後半の音符を独立して保持 (後半内の相対位置 j = 0 .. newHalf2 - 1 を newHalf1 + j に配置)
        const keepHalf2 = Math.min(oldHalf2, newHalf2);
        for (let j = 0; j < keepHalf2; j++) {
          const oldSlot = oldHalf1 + j;
          const newSlot = newHalf1 + j;
          if (oldRow[oldSlot] !== undefined && oldRow[oldSlot] !== '') {
            newRow[newSlot] = oldRow[oldSlot];
          }
        }

        m.notes[strIdx] = newRow;
      }
    }

    m.half1Divisions = newHalf1;
    m.half2Divisions = newHalf2;
  }

  // 半小節分割数変更ボックス
  createDivisionBox(label, currentVal, onChange) {
    const box = document.createElement('div');
    box.className = 'half-div-box';

    const lbl = document.createElement('span');
    lbl.className = 'half-div-label';
    lbl.textContent = label;
    box.appendChild(lbl);

    const minusBtn = document.createElement('button');
    minusBtn.className = 'div-btn';
    minusBtn.textContent = '-';
    minusBtn.title = '分割数を減らす (最小1)';
    minusBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (currentVal > 1) onChange(currentVal - 1);
    });
    box.appendChild(minusBtn);

    const valSpan = document.createElement('span');
    valSpan.className = 'div-val';
    valSpan.textContent = currentVal;
    box.appendChild(valSpan);

    const plusBtn = document.createElement('button');
    plusBtn.className = 'div-btn';
    plusBtn.textContent = '+';
    plusBtn.title = '分割数を増やす (最大16)';
    plusBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (currentVal < 16) onChange(currentVal + 1);
    });
    box.appendChild(plusBtn);

    return box;
  }

  // スロットセル（フレット番号入力欄）
  createSlotCell(measure, stringIndex, slotIndex, totalSlots) {
    const cell = document.createElement('div');
    cell.className = 'tab-slot-cell';
    cell.dataset.slotIndex = slotIndex;
    cell.dataset.stringIndex = stringIndex;
    cell.dataset.measureId = measure.id;

    // 半角数字のみ許可（全角数字は半角へ自動変換、最大2文字まで）
    const sanitizeHalfWidthDigits = (raw) => {
      return String(raw || '')
        .replace(/[０-９]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) - 0xFEE0))
        .replace(/[^0-9]/g, '')
        .slice(0, 2);
    };

    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'tab-slot-input';
    input.maxLength = 4;
    input.inputMode = 'numeric';
    input.setAttribute('pattern', '[0-9]*');
    input.style.imeMode = 'disabled';
    input.autocomplete = 'off';
    input.autocorrect = 'off';
    input.autocapitalize = 'off';
    input.spellcheck = false;

    // 既存の値
    const val = measure.notes && measure.notes[stringIndex] ? measure.notes[stringIndex][slotIndex] : '';
    if (val !== undefined && val !== '') {
      const sanitizedInit = sanitizeHalfWidthDigits(val);
      input.value = sanitizedInit;
      if (sanitizedInit !== '') {
        input.classList.add('has-note');
      }
    }

    // セル内の音符削除処理（ダブルクリック/ダブルタップ用）
    const clearNote = () => {
      if (!input.value && (!measure.notes || !measure.notes[stringIndex] || measure.notes[stringIndex][slotIndex] === undefined)) {
        return;
      }
      input.value = '';
      input.classList.remove('has-note');
      if (measure.notes && measure.notes[stringIndex]) {
        delete measure.notes[stringIndex][slotIndex];
      }
      this.app.saveState();
      this.app.pushHistory();
    };

    // テキスト上書き用フラグ（テキスト全選択を行わずに書き換え可能にする）
    let replaceOnNextInput = false;
    let valueAtFocus = '';

    // Android/Windowsでの「コピー、切り取り、すべて選択」メニューを抑止
    input.addEventListener('contextmenu', (e) => e.preventDefault());
    input.addEventListener('selectstart', (e) => e.preventDefault());

    input.addEventListener('focus', () => {
      // 選択メニュー（ActionMode）のポップアップを防ぐため input.select() は行わない
      // 代わりに次の文字入力時に上書きできるようにフラグを立てる
      if (input.value !== '') {
        replaceOnNextInput = true;
        valueAtFocus = input.value;
      } else {
        replaceOnNextInput = false;
        valueAtFocus = '';
      }
    });

    input.addEventListener('blur', () => {
      replaceOnNextInput = false;
      valueAtFocus = '';
    });

    // ソフトウェアキーボード等の入力時に既存値をスムーズに上書き＆半角数字以外を拒否
    input.addEventListener('beforeinput', (e) => {
      if (e.data) {
        const cleaned = sanitizeHalfWidthDigits(e.data);
        if (cleaned === '') {
          e.preventDefault();
          return;
        }
        if (replaceOnNextInput) {
          input.value = '';
          replaceOnNextInput = false;
        }
      }
    });

    // スタンプツールが選択されている場合はクリックでスタンプを配置
    input.addEventListener('mousedown', (e) => {
      if (this.app.stampManager.activeStampType) {
        e.preventDefault();
        e.stopPropagation();
        const wrapper = cell.closest('.tab-notation-wrapper');
        if (wrapper) {
          const rect = wrapper.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;
          this.app.stampManager.addStampToMeasure(measure, x, y);
        }
      }
    });

    // 入力イベント（半角数字のみ・最大2文字まで）
    input.addEventListener('input', () => {
      let rawVal = input.value;
      if (replaceOnNextInput) {
        if (valueAtFocus && rawVal.startsWith(valueAtFocus) && rawVal.length > valueAtFocus.length) {
          rawVal = rawVal.slice(valueAtFocus.length);
        }
        replaceOnNextInput = false;
      }

      const text = sanitizeHalfWidthDigits(rawVal);
      if (input.value !== text) {
        input.value = text;
      }

      if (!measure.notes) measure.notes = {};
      if (!measure.notes[stringIndex]) measure.notes[stringIndex] = {};

      if (text === '') {
        delete measure.notes[stringIndex][slotIndex];
        input.classList.remove('has-note');
      } else {
        measure.notes[stringIndex][slotIndex] = text;
        input.classList.add('has-note');

        // 音のプレビュー再生（入力した音を即聴ける！）
        this.app.playbackEngine.playGuitarPluck(stringIndex, text, 0.4);

        // 2文字入力完了時に次のスロットへ自動移動（1文字目入力後はそのまま2文字目を続けて入力可能）
        if (text.length >= 2) {
          this.moveToNextSlot(measure, stringIndex, slotIndex, totalSlots);
        }
      }
      this.app.saveState();
      this.app.pushHistory();
    });

    // キーボードナビゲーション（矢印キー、Enter、Backspace）
    input.addEventListener('keydown', (e) => {
      const str = parseInt(stringIndex, 10);
      const slot = parseInt(slotIndex, 10);

      if (e.key === 'ArrowRight') {
        e.preventDefault();
        const next = document.querySelector(
          `#measure-${measure.id} .tab-string-row[data-string-index="${str}"] .tab-slot-cell[data-slot-index="${slot + 1}"] input`
        );
        if (next) next.focus();
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        const prev = document.querySelector(
          `#measure-${measure.id} .tab-string-row[data-string-index="${str}"] .tab-slot-cell[data-slot-index="${slot - 1}"] input`
        );
        if (prev) prev.focus();
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        if (str > 0) {
          const up = document.querySelector(
            `#measure-${measure.id} .tab-string-row[data-string-index="${str - 1}"] .tab-slot-cell[data-slot-index="${slot}"] input`
          );
          if (up) up.focus();
        }
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        if (str < 5) {
          const down = document.querySelector(
            `#measure-${measure.id} .tab-string-row[data-string-index="${str + 1}"] .tab-slot-cell[data-slot-index="${slot}"] input`
          );
          if (down) down.focus();
        }
      } else if (e.key === 'Enter') {
        e.preventDefault();
        this.moveToNextSlot(measure, str, slot, totalSlots);
      } else if (e.key === 'Backspace' && input.value === '') {
        // 空白でBackspaceを押したら前のセルへ戻る
        const prev = document.querySelector(
          `#measure-${measure.id} .tab-string-row[data-string-index="${str}"] .tab-slot-cell[data-slot-index="${slot - 1}"] input`
        );
        if (prev) {
          prev.focus();
        }
      } else if (e.key && e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        const cleanedKey = sanitizeHalfWidthDigits(e.key);
        if (cleanedKey === '') {
          // 半角数字以外の入力を無効化
          e.preventDefault();
          return;
        }
        if (replaceOnNextInput) {
          // 通常キー入力時に既存値をクリアして上書き開始
          input.value = '';
          replaceOnNextInput = false;
        }
      }
    });

    // 【要件】タブ上の弦の番号をタップ/クリックしたときにそのキーの音が出るようにする（数字以外のテキストは無音）
    input.addEventListener('click', () => {
      if (this.app.stampManager && this.app.stampManager.activeStampType) return;
      const text = input.value.trim();
      if (/^\d+$/.test(text)) {
        this.app.playbackEngine.playGuitarPluck(stringIndex, text, 0.6);
      }
    });

    // セル枠のクリックでも音を再生しフォーカス
    cell.addEventListener('click', (e) => {
      if (e.target === input) return;
      if (this.app.stampManager && this.app.stampManager.activeStampType) return;
      const text = input.value.trim();
      if (/^\d+$/.test(text)) {
        this.app.playbackEngine.playGuitarPluck(stringIndex, text, 0.6);
      }
      input.focus();
    });

    // 【要件】Windows: ダブルクリックで削除
    input.addEventListener('dblclick', (e) => {
      e.preventDefault();
      e.stopPropagation();
      clearNote();
    });
    cell.addEventListener('dblclick', (e) => {
      e.preventDefault();
      e.stopPropagation();
      clearNote();
    });

    // 【要件】Android: ダブルタップで削除
    let lastTapTime = 0;
    const handleDoubleTap = (e) => {
      const now = Date.now();
      const timeDiff = now - lastTapTime;
      if (timeDiff > 0 && timeDiff < 350) {
        e.preventDefault();
        e.stopPropagation();
        clearNote();
        lastTapTime = 0;
        return;
      }
      lastTapTime = now;
    };

    input.addEventListener('touchend', handleDoubleTap);
    cell.addEventListener('touchend', handleDoubleTap);

    cell.appendChild(input);
    return cell;
  }

  // 弦入力後の自動移動（1〜5弦は真下の弦の同じ列、6弦は1弦の隣の列へ移動）
  moveToNextSlot(measure, stringIndex, slotIndex, totalSlots) {
    const str = parseInt(stringIndex, 10);
    const slot = parseInt(slotIndex, 10);

    let nextInput = null;
    if (str < 5) {
      // 1〜5弦の場合: 真下の弦 (str + 1) の同じ列 (slot) に移動
      nextInput = document.querySelector(
        `#measure-${measure.id} .tab-string-row[data-string-index="${str + 1}"] .tab-slot-cell[data-slot-index="${slot}"] input`
      );
    } else {
      // 6弦を入力した場合: 1弦 (0) の隣の列 (slot + 1) に移動
      if (slot + 1 < totalSlots) {
        nextInput = document.querySelector(
          `#measure-${measure.id} .tab-string-row[data-string-index="0"] .tab-slot-cell[data-slot-index="${slot + 1}"] input`
        );
      } else {
        // 小節末尾の6弦の場合: 次の小節があればその1弦・0列目へ移動
        const allMeasures = Array.from(document.querySelectorAll('.measure-card'));
        const currentCard = document.getElementById(`measure-${measure.id}`);
        const currentIndex = allMeasures.indexOf(currentCard);
        if (currentIndex !== -1 && currentIndex + 1 < allMeasures.length) {
          const nextCard = allMeasures[currentIndex + 1];
          nextInput = nextCard.querySelector('.tab-string-row[data-string-index="0"] .tab-slot-cell[data-slot-index="0"] input');
        }
      }
    }

    if (nextInput) {
      nextInput.focus();
    }
  }
}

