/**
 * スタンプマネージャー (StampManager)
 * 仕様：以下のスタンプを張り付けられる。張り付けたスタンプはサイズと角度をドラッグで変えられる
 * - c
 * - 横線
 * - 譜面のタイのマーク
 * - 全休符のマーク
 * - ４分休符のマーク
 * - テキスト自由入力
 */
import { generateId } from '../models/types.js';

export class StampManager {
  constructor(app) {
    this.app = app;
    this.activeStampType = null; // ツールバーで選択中のスタンプ
    this.selectedStampId = null; // 現在選択中の配置済みスタンプ
    this.isDragging = false;
    this.isTransforming = false; // リサイズまたは回転中
    this.transformMode = null; // 'rotate' | 'nw' | 'ne' | 'se' | 'sw'
    this.dragStart = { x: 0, y: 0 };
    this.initialTransform = { x: 0, y: 0, width: 0, height: 0, rotation: 0 };

    this.initGlobalListeners();
    this.initStampChipDrag();
  }

  // スタンプチップのドラッグ開始イベント初期化
  initStampChipDrag() {
    const bindChips = () => {
      document.querySelectorAll('.stamp-chip').forEach(chip => {
        chip.setAttribute('draggable', 'true');
        chip.addEventListener('dragstart', (e) => {
          const type = chip.dataset.stampType;
          if (type) {
            e.dataTransfer.setData('application/tabmaker-stamp', type);
            e.dataTransfer.effectAllowed = 'copy';
            chip.classList.add('dragging-source');
          }
        });

        chip.addEventListener('dragend', () => {
          chip.classList.remove('dragging-source');
        });
      });
    };

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', bindChips);
    } else {
      setTimeout(bindChips, 100);
    }
  }

  setActiveStampType(type) {
    this.activeStampType = type;
  }

  // スタンプのHTML/SVG表現を生成
  renderStampContent(stamp) {
    const color = stamp.color || '#38bdf8';
    switch (stamp.type) {
      case 'choke':
        return `<span class="stamp-choke" style="color: ${color};">c</span>`;

      case 'line':
        return `
          <svg width="100%" height="100%" viewBox="0 0 100 20" preserveAspectRatio="none">
            <line x1="2" y1="10" x2="98" y2="10" stroke="${color}" stroke-width="3" stroke-linecap="round" />
          </svg>
        `;

      case 'tie':
        // 上向きまたは下向きの美しいタイ（スラー弧線）
        return `
          <svg width="100%" height="100%" viewBox="0 0 100 40" preserveAspectRatio="none">
            <path d="M 5,30 Q 50,5 95,30 Q 50,15 5,30 Z" fill="${color}" />
          </svg>
        `;

      case 'wholeRest':
        // 全休符（第3線にぶら下がる休符記号）
        return `
          <svg width="100%" height="100%" viewBox="0 0 40 24" preserveAspectRatio="xMidYMid meet">
            <rect x="2" y="4" width="36" height="12" fill="${color}" rx="1" />
            <line x1="0" y1="4" x2="40" y2="4" stroke="${color}" stroke-width="2" />
          </svg>
        `;

      case 'quarterRest':
        // 4分休符記号（クラシックな稲妻型の休符）
        return `
          <svg width="100%" height="100%" viewBox="0 0 30 50" preserveAspectRatio="xMidYMid meet">
            <path d="M 18,2 L 10,14 L 20,24 C 20,24 10,32 16,36 C 22,40 18,48 10,48 C 6,48 6,44 10,42 C 14,40 16,36 12,32 L 20,24 L 12,14 Z" fill="${color}" />
          </svg>
        `;

      case 'text':
      default:
        const fontSize = Math.max(9, Math.round((stamp.height || 26) * 0.52));
        return `<span class="stamp-text" style="color: ${color}; font-size: ${fontSize}px;">${stamp.text || 'テキスト'}</span>`;
    }
  }

  // 小節内にスタンプDOMをレンダリング
  renderStampsForMeasure(measure, containerEl) {
    containerEl.innerHTML = '';
    const stamps = measure.stamps || [];

    stamps.forEach(stamp => {
      const isSelected = this.selectedStampId === stamp.id;
      const el = document.createElement('div');
      el.className = `stamp-item ${isSelected ? 'selected' : ''}`;
      el.dataset.stampId = stamp.id;
      el.dataset.measureId = measure.id;

      // 位置、サイズ、回転
      el.style.left = `${stamp.x}px`;
      el.style.top = `${stamp.y}px`;
      el.style.width = `${stamp.width}px`;
      el.style.height = `${stamp.height}px`;
      el.style.transform = `rotate(${stamp.rotation || 0}deg)`;

      // コンテンツ
      el.innerHTML = `
        <div class="stamp-content">
          ${this.renderStampContent(stamp)}
        </div>
      `;

      // 選択されている場合はハンドルを表示
      if (isSelected) {
        this.attachHandles(el, measure, stamp);
      }

      // スタンプのポインター/マウスダウンイベント（選択＆移動・変形開始：モバイルタッチ両対応）
      el.addEventListener('pointerdown', (e) => this.handleStampPointerDown(e, measure, stamp));

      // テキストスタンプのダブルクリック（テキスト編集）
      if (stamp.type === 'text') {
        el.addEventListener('dblclick', (e) => {
          e.stopPropagation();
          const newText = prompt('テキストを入力してください:', stamp.text || '');
          if (newText !== null) {
            stamp.text = newText;
            // 日本語・全角文字を考慮した幅の自動調整
            let estimatedWidth = 16;
            for (let i = 0; i < newText.length; i++) {
              estimatedWidth += newText.charCodeAt(i) > 255 ? 16 : 9;
            }
            stamp.width = Math.max(45, estimatedWidth);
            this.app.saveStateAndRender();
          }
        });
      }

      containerEl.appendChild(el);
    });
  }

  // スタンプの追加（種類と位置を直接指定：ドラッグ＆ドロップ対応）
  addStampToMeasureWithType(measure, stampType, x, y, containerWidth = null, containerHeight = null) {
    if (!stampType) return;

    let width = 40;
    let height = 30;
    let text = '';
    let color = '#2563eb';

    switch (stampType) {
      case 'choke':
        width = 30;
        height = 30;
        color = '#dc2626'; // 鮮やかな赤
        break;
      case 'line':
        width = 60;
        height = 16;
        color = '#059669'; // 鮮やかな緑
        break;
      case 'tie':
        width = 70;
        height = 28;
        color = '#2563eb'; // 鮮やかな青
        break;
      case 'wholeRest':
        width = 32;
        height = 20;
        color = '#d97706'; // 鮮やかなアンバー
        break;
      case 'quarterRest':
        width = 24;
        height = 40;
        color = '#d97706'; // 鮮やかなアンバー
        break;
      case 'text':
        text = prompt('スタンプのテキストを入力してください:', 'P.M.') || '注記';
        let estimatedWidth = 16;
        for (let i = 0; i < text.length; i++) {
          estimatedWidth += text.charCodeAt(i) > 255 ? 16 : 9;
        }
        width = Math.max(45, estimatedWidth);
        height = 26;
        color = '#0f172a'; // 濃い黒
        break;
    }

    const newStamp = {
      id: generateId('st'),
      type: stampType,
      x: Math.max(0, Math.round(x - width / 2)),
      y: Math.max(0, Math.round(y - height / 2)),
      width: width,
      height: height,
      rotation: 0,
      color: color,
      text: text,
      measureWidth: Math.round(containerWidth || 320),
      measureHeight: Math.round(containerHeight || 180)
    };

    if (!measure.stamps) measure.stamps = [];
    measure.stamps.push(newStamp);
    this.selectedStampId = newStamp.id;

    // スタンプ配置後はアクティブスタンプを解除
    this.activeStampType = null;
    this.app.updateStampChipsActiveState();
    this.app.saveStateAndRender();
    this.app.showToast('スタンプを配置しました（ドラッグで移動・変形可能）');
  }

  // スタンプの追加（小節内のクリック位置へ：後方互換）
  addStampToMeasure(measure, x, y, containerWidth = null, containerHeight = null) {
    if (!this.activeStampType) return;
    this.addStampToMeasureWithType(measure, this.activeStampType, x, y, containerWidth, containerHeight);
  }

  // スタンプの削除
  deleteStamp(measureId, stampId) {
    const measure = this.app.findMeasureById(measureId);
    if (!measure || !measure.stamps) return;
    measure.stamps = measure.stamps.filter(s => s.id !== stampId);
    if (this.selectedStampId === stampId) {
      this.selectedStampId = null;
    }
    this.app.saveStateAndRender();
  }

  // スタンプの変形ハンドル・削除ボタンをDOM要素に付与
  attachHandles(el, measure, stamp) {
    el.querySelectorAll('.stamp-handle, .stamp-delete-btn').forEach(node => node.remove());

    // 回転ハンドル
    const rotateHandle = document.createElement('div');
    rotateHandle.className = 'stamp-handle handle-rotate';
    rotateHandle.title = 'ドラッグして角度を変更';
    rotateHandle.dataset.handle = 'rotate';
    el.appendChild(rotateHandle);

    // 四隅リサイズハンドル
    ['nw', 'ne', 'se', 'sw'].forEach(corner => {
      const cornerHandle = document.createElement('div');
      cornerHandle.className = `stamp-handle handle-${corner}`;
      cornerHandle.title = 'ドラッグしてサイズを変更';
      cornerHandle.dataset.handle = corner;
      el.appendChild(cornerHandle);
    });

    // 削除ボタン
    const delBtn = document.createElement('button');
    delBtn.className = 'stamp-delete-btn';
    delBtn.innerHTML = '×';
    delBtn.title = 'スタンプを削除';
    delBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.deleteStamp(measure.id, stamp.id);
    });
    el.appendChild(delBtn);
  }

  // DOM全体を再描画せずに局所的にスタンプを選択
  selectStampLocally(measure, stamp, stampEl) {
    if (this.selectedStampId === stamp.id && stampEl.classList.contains('selected')) {
      return;
    }

    // 全てのスタンプの選択状態を解除
    document.querySelectorAll('.stamp-item.selected').forEach(item => {
      item.classList.remove('selected');
      item.querySelectorAll('.stamp-handle, .stamp-delete-btn').forEach(node => node.remove());
    });

    this.selectedStampId = stamp.id;
    stampEl.classList.add('selected');
    this.attachHandles(stampEl, measure, stamp);
  }

  // ポインターダウン処理（マウス・タッチ両対応）
  handleStampPointerDown(e, measure, stamp) {
    if (e.target.classList.contains('stamp-delete-btn')) return;

    e.stopPropagation();
    if (e.cancelable && e.pointerType === 'touch') {
      e.preventDefault();
    }

    const stampEl = e.currentTarget;
    this.currentMeasure = measure;
    this.currentStamp = stamp;

    // クリックされたスタンプを選択（DOM全体を再描画せずローカルに反映）
    this.selectStampLocally(measure, stamp, stampEl);

    const handle = e.target.dataset.handle;
    if (handle) {
      // ハンドルによる変形（回転またはリサイズ）
      this.isTransforming = true;
      this.transformMode = handle;
    } else {
      // 移動ドラッグ
      this.isDragging = true;
    }

    const clientX = e.clientX ?? (e.touches && e.touches[0] ? e.touches[0].clientX : 0);
    const clientY = e.clientY ?? (e.touches && e.touches[0] ? e.touches[0].clientY : 0);

    this.dragStart = { x: clientX, y: clientY };
    this.initialTransform = {
      x: stamp.x,
      y: stamp.y,
      width: stamp.width,
      height: stamp.height,
      rotation: stamp.rotation || 0
    };

    // 中心座標を記録（回転計算用）
    const rect = stampEl.getBoundingClientRect();
    this.stampCenter = {
      x: rect.left + rect.width / 2,
      y: rect.top + rect.height / 2
    };

    if (e.pointerId && stampEl.setPointerCapture) {
      try {
        stampEl.setPointerCapture(e.pointerId);
        this.capturedPointerId = e.pointerId;
        this.capturedElement = stampEl;
      } catch (err) {}
    }
  }

  handleMove(clientX, clientY) {
    if (!this.currentStamp) return;

    const dx = clientX - this.dragStart.x;
    const dy = clientY - this.dragStart.y;

    if (this.isDragging) {
      // 位置移動
      this.currentStamp.x = Math.max(0, Math.round(this.initialTransform.x + dx));
      this.currentStamp.y = Math.max(0, Math.round(this.initialTransform.y + dy));
      this.app.renderFastStampUpdate(this.currentStamp);
    } else if (this.isTransforming) {
      if (this.transformMode === 'rotate') {
        // 回転角度の計算（マウス/タッチ座標と中心のなす角）
        const radians = Math.atan2(clientY - this.stampCenter.y, clientX - this.stampCenter.x);
        let degrees = Math.round(radians * (180 / Math.PI)) + 90; // 上が0度
        this.currentStamp.rotation = degrees;
      } else {
        // リサイズ計算
        let newW = this.initialTransform.width;
        let newH = this.initialTransform.height;

        if (this.transformMode === 'se') {
          newW = Math.max(16, this.initialTransform.width + dx);
          newH = Math.max(12, this.initialTransform.height + dy);
        } else if (this.transformMode === 'sw') {
          newW = Math.max(16, this.initialTransform.width - dx);
          newH = Math.max(12, this.initialTransform.height + dy);
          this.currentStamp.x = this.initialTransform.x + dx;
        } else if (this.transformMode === 'ne') {
          newW = Math.max(16, this.initialTransform.width + dx);
          newH = Math.max(12, this.initialTransform.height - dy);
          this.currentStamp.y = this.initialTransform.y + dy;
        } else if (this.transformMode === 'nw') {
          newW = Math.max(16, this.initialTransform.width - dx);
          newH = Math.max(12, this.initialTransform.height - dy);
          this.currentStamp.x = this.initialTransform.x + dx;
          this.currentStamp.y = this.initialTransform.y + dy;
        }

        this.currentStamp.width = Math.round(newW);
        this.currentStamp.height = Math.round(newH);
      }
      this.app.renderFastStampUpdate(this.currentStamp);
    }
  }

  handleEnd() {
    if (this.isDragging || this.isTransforming) {
      this.isDragging = false;
      this.isTransforming = false;
      this.transformMode = null;
      if (this.capturedElement && this.capturedPointerId !== null && this.capturedPointerId !== undefined) {
        try {
          this.capturedElement.releasePointerCapture(this.capturedPointerId);
        } catch (err) {}
        this.capturedPointerId = null;
        this.capturedElement = null;
      }
      this.app.saveState();
      this.app.pushHistory();
    }
  }

  initGlobalListeners() {
    window.addEventListener('pointermove', (e) => {
      if (this.isDragging || this.isTransforming) {
        this.handleMove(e.clientX, e.clientY);
      }
    });

    window.addEventListener('touchmove', (e) => {
      if (this.isDragging || this.isTransforming) {
        if (e.cancelable) e.preventDefault();
        const touch = e.touches[0];
        if (touch) this.handleMove(touch.clientX, touch.clientY);
      }
    }, { passive: false });

    window.addEventListener('pointerup', () => this.handleEnd());
    window.addEventListener('pointercancel', () => this.handleEnd());
    window.addEventListener('touchend', () => this.handleEnd());

    // 画面外クリックでスタンプ選択解除
    window.addEventListener('click', (e) => {
      if (!e.target.closest('.stamp-item') && !e.target.closest('.stamp-chips')) {
        if (this.selectedStampId) {
          this.selectedStampId = null;
          document.querySelectorAll('.stamp-item.selected').forEach(el => {
            el.classList.remove('selected');
            el.querySelectorAll('.stamp-handle, .stamp-delete-btn').forEach(node => node.remove());
          });
        }
      }
    });

    // Deleteキーで選択中スタンプ削除
    window.addEventListener('keydown', (e) => {
      if ((e.key === 'Delete' || e.key === 'Backspace') && this.selectedStampId) {
        // 入力フィールド内では無効
        if (['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName)) return;
        if (this.currentMeasure) {
          this.deleteStamp(this.currentMeasure.id, this.selectedStampId);
        }
      }
    });
  }
}
