/**
 * TabMaker メインアプリケーションコントローラー
 */
import {
  createNewSong,
  createNewSection,
  COLOR_PALETTE,
  SECTION_COLOR_PALETTE,
  MEASURE_COLOR_PALETTE,
  generateId
} from './models/types.js';
import { getSampleSong } from './models/sampleData.js';
import { SectionView } from './components/SectionView.js';
import { StampManager } from './components/StampManager.js';
import { PlaybackEngine } from './audio/PlaybackEngine.js';
import {
  exportToGoogleSheetsExcel,
  openExportFolder,
  selectExportFolder,
  setExportFolder,
  getExportSettings,
  shareExportedFile
} from './exporters/excelExporter.js';
import {
  exportToPdf,
  getSavedPrintSettings,
  savePrintSettings
} from './exporters/pdfExporter.js';
import {
  isAndroidApp,
  getAndroidExportSettings,
  saveAndroidExportSettings
} from './utils/platform.js';

const STORAGE_KEY = 'tabmaker_current_song';
const STORAGE_PROJECTS_INDEX_KEY = 'tabmaker_projects_index';
const STORAGE_PROJECT_DATA_PREFIX = 'tabmaker_project_data_';

function escapeHtml(str) {
  return String(str || '').replace(/[&<>'"]/g, tag => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    "'": '&#39;',
    '"': '&quot;'
  }[tag] || tag));
}

export class TabMakerApp {
  constructor() {
    this.song = null;
    this.history = [];
    this.historyIndex = -1;

    this.clipboardMeasure = null;
    this.clipboardSection = null;
    this.activeSectionId = null;
    this.currentPlayingSectionId = null; // 現在再生中のセクションID

    this.stampManager = new StampManager(this);
    this.playbackEngine = new PlaybackEngine();

    this.initAudioCallbacks();
    this.loadInitialSong();
    this.initDOM();
    this.initKeyboardShortcuts();
    this.render();
  }

  // 初期楽曲データの読み込み
  loadInitialSong() {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        this.song = JSON.parse(saved);
      } else {
        // 初回はサンプル曲（壊れた空風のリアルな例）を読み込み
        this.song = getSampleSong();
      }
    } catch (e) {
      console.error('保存データの読み込みに失敗しました:', e);
      this.song = getSampleSong();
    }
    this.activeSectionId = this.song?.sections?.[0]?.id || null;
    this.pushHistory();

    // 初回プロジェクト一覧の初期化（未保存なら現在の曲を初期プロジェクトとして登録）
    try {
      const projects = this.getSavedProjects();
      if (projects.length === 0 && this.song) {
        if (!this.song.projectId) this.song.projectId = generateId('proj');
        let measureCount = 0;
        (this.song.sections || []).forEach(s => measureCount += (s.measures || []).length);
        const initialMeta = {
          id: this.song.projectId,
          title: this.song.title || '壊れた空 (サンプルタブ譜)',
          artist: this.song.artist || 'Sample Band',
          bpm: this.song.bpm || 96,
          measureCount: measureCount,
          sectionCount: (this.song.sections || []).length,
          updatedAt: new Date().toISOString()
        };
        localStorage.setItem(STORAGE_PROJECTS_INDEX_KEY, JSON.stringify([initialMeta]));
        localStorage.setItem(`${STORAGE_PROJECT_DATA_PREFIX}${this.song.projectId}`, JSON.stringify(this.song));
      }
    } catch (e) {}
  }

  // 音声再生エンジンのコールバック設定
  initAudioCallbacks() {
    this.playbackEngine.onTick = (measureId, slotIndex) => {
      // 直前のハイライトをクリア
      document.querySelectorAll('.measure-card.playback-active, .tab-slot-cell.playback-active').forEach(el => {
        el.classList.remove('playback-active');
      });

      // 現在の小節をハイライト
      const measEl = document.querySelector(`#measure-${measureId}`);
      if (measEl) {
        measEl.classList.add('playback-active');
        // 縦に同一で並んだ6弦すべて（1弦〜6弦）の同一スロットセルをいっぺんにハイライト
        const slotCells = measEl.querySelectorAll(`.tab-slot-cell[data-slot-index="${slotIndex}"]`);
        slotCells.forEach(cell => {
          cell.classList.add('playback-active');
        });
      }
    };

    this.playbackEngine.onStop = () => {
      document.querySelectorAll('.measure-card.playback-active, .tab-slot-cell.playback-active').forEach(el => {
        el.classList.remove('playback-active');
      });
      this.currentPlayingSectionId = null;
      this.updateSectionPlayButtons();
    };
  }

  // ヘッダー用ドロップダウンメニュー（出力・プロジェクト）の初期化
  initDropdowns() {
    const exportDropdown = document.querySelector('#export-dropdown-container');
    const projectDropdown = document.querySelector('#project-dropdown-container');
    const exportBtn = document.querySelector('#export-dropdown-btn');
    const projectBtn = document.querySelector('#project-dropdown-btn');
    const exportMenu = document.querySelector('#export-dropdown-menu');
    const projectMenu = document.querySelector('#project-dropdown-menu');
    const headerActions = document.querySelector('.header-actions');

    const updateMenuPosition = (btn, menu) => {
      if (!btn || !menu) return;
      const isMobile = window.innerWidth <= 1024;
      if (isMobile) {
        const rect = btn.getBoundingClientRect();
        menu.style.position = 'fixed';
        menu.style.top = `${rect.bottom + 6}px`;

        const menuWidth = 230;
        if (rect.right > window.innerWidth - 10) {
          menu.style.right = '8px';
          menu.style.left = 'auto';
        } else if (rect.left + menuWidth > window.innerWidth) {
          menu.style.right = '8px';
          menu.style.left = 'auto';
        } else {
          menu.style.left = `${Math.max(8, rect.left)}px`;
          menu.style.right = 'auto';
        }
      } else {
        menu.style.position = '';
        menu.style.top = '';
        menu.style.left = '';
        menu.style.right = '';
      }
    };

    const closeAllDropdowns = () => {
      if (exportDropdown) {
        exportDropdown.classList.remove('open');
        exportBtn?.setAttribute('aria-expanded', 'false');
      }
      if (projectDropdown) {
        projectDropdown.classList.remove('open');
        projectBtn?.setAttribute('aria-expanded', 'false');
      }
    };

    if (exportBtn && exportDropdown) {
      exportBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        const isOpen = exportDropdown.classList.contains('open');
        closeAllDropdowns();
        if (!isOpen) {
          updateMenuPosition(exportBtn, exportMenu);
          exportDropdown.classList.add('open');
          exportBtn.setAttribute('aria-expanded', 'true');
        }
      });
    }

    if (projectBtn && projectDropdown) {
      projectBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        const isOpen = projectDropdown.classList.contains('open');
        closeAllDropdowns();
        if (!isOpen) {
          updateMenuPosition(projectBtn, projectMenu);
          projectDropdown.classList.add('open');
          projectBtn.setAttribute('aria-expanded', 'true');
        }
      });
    }

    // ドロップダウン内のアイテムをクリックしたら即座に閉じる
    document.querySelectorAll('.dropdown-item').forEach(item => {
      item.addEventListener('click', () => {
        closeAllDropdowns();
      });
    });

    // 画面外クリックで閉じる
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.dropdown-container')) {
        closeAllDropdowns();
      }
    });

    // ヘッダー行をスワイプ（スクロール）したらドロップダウンを自動で閉じる
    if (headerActions) {
      headerActions.addEventListener('scroll', () => {
        closeAllDropdowns();
      }, { passive: true });
    }

    // ESCキーで閉じる
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeAllDropdowns();
      }
    });
  }

  // DOMイベントの初期化
  initDOM() {
    if (isAndroidApp()) {
      document.body.classList.add('is-android-app');
    }
    this.initDropdowns();

    // 曲名・アーティスト・BPM入力
    const titleInput = document.querySelector('#song-title-input');
    const artistInput = document.querySelector('#song-artist-input');
    const bpmInput = document.querySelector('#song-bpm-input');

    if (titleInput) {
      titleInput.value = this.song.title || '';
      titleInput.addEventListener('input', (e) => {
        this.song.title = e.target.value;
        this.saveState();
      });
      titleInput.addEventListener('change', () => {
        this.pushHistory();
      });
    }

    if (artistInput) {
      artistInput.value = this.song.artist || '';
      artistInput.addEventListener('input', (e) => {
        this.song.artist = e.target.value;
        this.saveState();
      });
      artistInput.addEventListener('change', () => {
        this.pushHistory();
      });
    }

    if (bpmInput) {
      bpmInput.value = this.song.bpm || 120;
      bpmInput.addEventListener('input', (e) => {
        this.song.bpm = parseInt(e.target.value, 10) || 120;
        this.saveState();
      });
      bpmInput.addEventListener('change', () => {
        this.pushHistory();
      });
    }

    // ドラッグハンドル以外の場所をタップ・クリックした際に「移動中」ポップアップの残存を一括消去
    const clearAllDragFloatingPreviews = (e) => {
      if (e.target && e.target.closest && (e.target.closest('.measure-drag-handle') || e.target.closest('.section-drag-handle'))) {
        return;
      }
      const previews = document.querySelectorAll('.drag-floating-preview');
      if (previews.length > 0) {
        previews.forEach(el => el.remove());
        document.querySelectorAll('.is-dragging-measure').forEach(el => el.classList.remove('is-dragging-measure'));
        document.querySelectorAll('.is-dragging-section').forEach(el => el.classList.remove('is-dragging-section'));
        document.querySelectorAll('.drag-over-before, .drag-over-after, .drag-over-top, .drag-over-bottom').forEach(el => {
          el.classList.remove('drag-over-before', 'drag-over-after', 'drag-over-top', 'drag-over-bottom');
        });
      }
    };
    window.addEventListener('pointerdown', clearAllDragFloatingPreviews, { capture: true });
    window.addEventListener('touchstart', clearAllDragFloatingPreviews, { capture: true, passive: true });

    // セクション追加ボタン
    const addSectionBtn = document.querySelector('#add-section-btn');
    if (addSectionBtn) {
      addSectionBtn.addEventListener('click', () => {
        const newSec = createNewSection('aメロ', { measureCount: 4 });
        this.song.sections.push(newSec);
        this.activeSectionId = newSec.id;
        this.renumberMeasures();
        this.saveStateAndRender();
        this.showToast('新しいセクションを追加しました');
      });
    }

    // コードセクション追加ボタン（トップ行＋コード入力行＋ボトム行、デフォルト1行＝4小節）
    const addChordSectionBtn = document.querySelector('#add-chord-section-btn');
    if (addChordSectionBtn) {
      addChordSectionBtn.addEventListener('click', () => {
        const newSec = createNewSection('aメロ', { isChordOnly: true, measureCount: 4 });
        this.song.sections.push(newSec);
        this.activeSectionId = newSec.id;
        this.renumberMeasures();
        this.saveStateAndRender();
        this.showToast('コードセクションを追加しました');
      });
    }

    // 省略セクション追加ボタン（セクション名だけのバーを追加）
    const addCompactSectionBtn = document.querySelector('#add-compact-section-btn');
    if (addCompactSectionBtn) {
      addCompactSectionBtn.addEventListener('click', () => {
        const newSec = createNewSection('aメロ', { isCompact: true });
        this.song.sections.push(newSec);
        this.activeSectionId = newSec.id;
        this.renumberMeasures();
        this.saveStateAndRender();
        this.showToast('省略セクションを追加しました');
      });
    }

    // スタンプパレットのイベント
    document.querySelectorAll('.stamp-chip').forEach(chip => {
      chip.addEventListener('click', () => {
        const type = chip.dataset.stampType;
        if (this.stampManager.activeStampType === type) {
          // すでにアクティブなら解除
          this.stampManager.setActiveStampType(null);
        } else {
          this.stampManager.setActiveStampType(type);
        }
        this.updateStampChipsActiveState();
      });
    });

    // 1. 通常のエクスポートボタン（即座に確実にダウンロード＆保存）
    const exportExcelBtn = document.querySelector('#export-excel-btn');
    if (exportExcelBtn) {
      exportExcelBtn.addEventListener('click', async () => {
        this.showToast('Googleスプレッドシート用Excelファイルを生成中...');
        try {
          const result = await exportToGoogleSheetsExcel(this.song);
          this.showExportSuccessModal(result);
          this.showToast('Excelファイルのダウンロードと保存が完了しました！');
        } catch (err) {
          console.error('Excelエクスポートエラー:', err);
          alert('Excelファイルの生成中にエラーが発生しました: ' + err.message);
        }
      });
    }

    // 2. ツールバーのフォルダ設定バッジとモーダル制御
    this.refreshFolderDisplay();

    const folderModal = document.querySelector('#folder-settings-modal');
    const openFolderModal = () => {
      this.syncFolderModalInputs();
      if (folderModal) folderModal.classList.add('open');
    };

    const currentFolderBadge = document.querySelector('#current-folder-badge');
    if (currentFolderBadge) {
      currentFolderBadge.addEventListener('click', (e) => {
        // ボタンクリックとバッジ自体のクリックの両方に対応
        openFolderModal();
      });
    }

    const selectFolderBtn = document.querySelector('#select-folder-btn');
    if (selectFolderBtn) {
      selectFolderBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openFolderModal();
      });
    }

    if (folderModal) {
      // プリセットボタン
      folderModal.querySelectorAll('.preset-folder-btn').forEach(btn => {
        btn.addEventListener('click', async () => {
          const presetKey = btn.dataset.preset;
          const settings = await getExportSettings();
          if (settings.presetDirs && settings.presetDirs[presetKey]) {
            const targetPath = settings.presetDirs[presetKey];
            const res = await setExportFolder(targetPath);
            if (res && res.success) {
              this.showToast(`保存先フォルダを「${targetPath}」に設定しました`);
              this.refreshFolderDisplay();
              folderModal.classList.remove('open');
            }
          }
        });
      });

      // Windowsフォルダ参照画面を開くボタン
      const browseWinBtn = folderModal.querySelector('#browse-windows-dialog-btn');
      if (browseWinBtn) {
        browseWinBtn.addEventListener('click', async () => {
          this.showToast('Windowsのフォルダ参照画面を開いています...');
          const res = await selectExportFolder();
          if (res && !res.cancelled && res.outputDir) {
            this.showToast(`保存先フォルダを設定しました:\n${res.outputDir}`);
            this.refreshFolderDisplay();
            folderModal.classList.remove('open');
          } else {
            this.showToast('フォルダ選択がキャンセルされました');
          }
        });
      }

      // 手動パス設定ボタン
      const saveManualBtn = folderModal.querySelector('#save-manual-folder-btn');
      const manualInput = folderModal.querySelector('#manual-folder-input');
      if (saveManualBtn && manualInput) {
        saveManualBtn.addEventListener('click', async () => {
          const val = manualInput.value.trim();
          if (!val) {
            alert('フォルダのパスを入力してください');
            return;
          }
          const res = await setExportFolder(val);
          if (res && res.success) {
            this.showToast(`保存先フォルダを更新しました:\n${res.outputDir}`);
            this.refreshFolderDisplay();
            folderModal.classList.remove('open');
          } else {
            alert(res.error || 'フォルダが存在しないかアクセスできません');
          }
        });
      }

      // モーダル内の「現在の保存先を開く」
      const modalTestOpenBtn = folderModal.querySelector('#modal-test-open-btn');
      if (modalTestOpenBtn) {
        modalTestOpenBtn.addEventListener('click', () => {
          openExportFolder();
        });
      }

      // 閉じるボタン
      folderModal.querySelectorAll('.modal-close-btn').forEach(b => {
        b.addEventListener('click', () => folderModal.classList.remove('open'));
      });
      folderModal.addEventListener('click', (e) => {
        if (e.target === folderModal) folderModal.classList.remove('open');
      });
    }

    // 4. ツールバーのフォルダを開くボタン
    const openFolderBtn = document.querySelector('#open-folder-btn');
    if (openFolderBtn) {
      openFolderBtn.addEventListener('click', async () => {
        if (isAndroidApp()) {
          openFolderModal();
        } else {
          const opened = await openExportFolder();
          if (!opened) {
            this.showToast('📁 Web版ではお使いのブラウザの「ダウンロード」フォルダ（Ctrl + J）に保存されます');
          }
        }
      });
    }

    // エクスポートボタン（PDF / 印刷設定モーダル）
    const exportPdfBtn = document.querySelector('#export-pdf-btn');
    const printModal = document.querySelector('#print-settings-modal');
    if (exportPdfBtn && printModal) {
      exportPdfBtn.addEventListener('click', () => {
        this.openPrintSettingsModal();
      });

      // 印刷設定モーダル内の向きラジオカードの切り替え
      printModal.querySelectorAll('.print-orient-card').forEach(card => {
        card.addEventListener('click', () => {
          printModal.querySelectorAll('.print-orient-card').forEach(c => c.classList.remove('active'));
          card.classList.add('active');
          const radio = card.querySelector('input[type="radio"]');
          if (radio) radio.checked = true;
        });
      });

      // 印刷プレビュー / PDF保存実行
      const executePrintBtn = printModal.querySelector('#execute-print-btn');
      if (executePrintBtn) {
        executePrintBtn.addEventListener('click', async () => {
          if (executePrintBtn.disabled) return;

          const selectedRadio = printModal.querySelector('input[name="print-orientation-radio"]:checked');
          const orientation = selectedRadio ? selectedRadio.value : 'portrait';
          const pageSize = printModal.querySelector('#print-page-size-select')?.value || 'A4';
          const measuresPerRow = parseInt(printModal.querySelector('#print-measures-per-row-select')?.value, 10) || 4;
          const margin = printModal.querySelector('#print-margin-select')?.value || '10mm';
          const showPrintHeader = printModal.querySelector('#print-opt-header')?.checked ?? true;
          const showSectionFooter = printModal.querySelector('#print-opt-footer')?.checked ?? true;

          const settings = {
            orientation,
            pageSize,
            measuresPerRow,
            margin,
            showPrintHeader,
            showSectionFooter
          };

          savePrintSettings(settings);
          printModal.classList.remove('open');

          if (isAndroidApp()) {
            this.showToast('🖨️ 印刷プレビュー（PDF保存）を起動中...');
          }

          try {
            executePrintBtn.disabled = true;
            await exportToPdf(settings);
          } catch (err) {
            console.error('PDF出力エラー:', err);
            this.showToast('PDF印刷の起動に失敗しました: ' + (err.message || ''), 'error');
          } finally {
            executePrintBtn.disabled = false;
          }
        });
      }

      // モーダル閉じるボタン
      printModal.querySelectorAll('.modal-close-btn').forEach(btn => {
        btn.addEventListener('click', () => printModal.classList.remove('open'));
      });
      printModal.addEventListener('click', (e) => {
        if (e.target === printModal) printModal.classList.remove('open');
      });
    }

    // サンプル曲読み込みボタン
    const loadSampleBtn = document.querySelector('#load-sample-btn');
    if (loadSampleBtn) {
      loadSampleBtn.addEventListener('click', () => {
        if (confirm('サンプル曲「壊れた空」を読み込みますか？現在の変更は上書きされます。')) {
          this.song = getSampleSong();
          this.activeSectionId = this.song?.sections?.[0]?.id || null;
          this.syncInputsWithSong();
          this.saveStateAndRender();
          this.showToast('サンプル曲を読み込みました');
        }
      });
    }

    // 新規作成ボタン
    const newSongBtn = document.querySelector('#new-song-btn');
    if (newSongBtn) {
      newSongBtn.addEventListener('click', () => {
        if (confirm('新しいタブ譜を作成しますか？')) {
          this.song = createNewSong('無題のタブ譜', 'アーティスト');
          this.activeSectionId = this.song?.sections?.[0]?.id || null;
          this.syncInputsWithSong();
          this.saveStateAndRender();
          this.showToast('新しいタブ譜を作成しました');
        }
      });
    }

    // Undo / Redo ボタン
    const undoBtn = document.querySelector('#undo-btn');
    const redoBtn = document.querySelector('#redo-btn');
    if (undoBtn) undoBtn.addEventListener('click', () => this.undo());
    if (redoBtn) redoBtn.addEventListener('click', () => this.redo());

    // ヘルプモーダル
    const helpBtn = document.querySelector('#help-btn');
    const helpModal = document.querySelector('#help-modal');
    if (helpBtn && helpModal) {
      helpBtn.addEventListener('click', () => helpModal.classList.add('open'));
      helpModal.querySelector('.modal-close-btn').addEventListener('click', () => helpModal.classList.remove('open'));
      helpModal.addEventListener('click', (e) => {
        if (e.target === helpModal) helpModal.classList.remove('open');
      });
    }

    // プロジェクト保存ボタン
    const saveProjectBtn = document.querySelector('#save-project-btn');
    if (saveProjectBtn) {
      saveProjectBtn.addEventListener('click', () => this.saveCurrentProject());
    }

    // プロジェクト一覧・管理ボタン
    const openProjectsBtn = document.querySelector('#open-projects-btn');
    if (openProjectsBtn) {
      openProjectsBtn.addEventListener('click', () => this.openProjectManagerModal());
    }

    // プロジェクト複製ボタン（ヘッダードロップダウン内）
    const duplicateProjectBtn = document.querySelector('#duplicate-project-btn');
    if (duplicateProjectBtn) {
      duplicateProjectBtn.addEventListener('click', () => this.duplicateCurrentProject());
    }

    // プロジェクト管理モーダル内の各種ボタン
    const projModal = document.querySelector('#project-manager-modal');
    if (projModal) {
      const modalSaveBtn = projModal.querySelector('#modal-save-current-btn');
      if (modalSaveBtn) {
        modalSaveBtn.addEventListener('click', () => this.saveCurrentProject());
      }

      const modalDuplicateBtn = projModal.querySelector('#modal-duplicate-current-btn');
      if (modalDuplicateBtn) {
        modalDuplicateBtn.addEventListener('click', () => this.duplicateCurrentProject());
      }

      const modalNewBtn = projModal.querySelector('#modal-new-project-btn');
      if (modalNewBtn) {
        modalNewBtn.addEventListener('click', () => {
          projModal.classList.remove('open');
          const newBtn = document.querySelector('#new-song-btn');
          if (newBtn) newBtn.click();
        });
      }

      const modalImportBtn = projModal.querySelector('#modal-import-file-btn');
      const fileInput = document.querySelector('#project-file-input');
      if (modalImportBtn && fileInput) {
        modalImportBtn.addEventListener('click', () => fileInput.click());
      }

      if (fileInput) {
        fileInput.addEventListener('change', (e) => {
          const file = e.target.files?.[0];
          if (file) {
            this.importProjectFromFile(file);
            fileInput.value = '';
          }
        });
      }

      const closeBtn = projModal.querySelector('.modal-close-btn');
      if (closeBtn) closeBtn.addEventListener('click', () => projModal.classList.remove('open'));
      projModal.addEventListener('click', (e) => {
        if (e.target === projModal) projModal.classList.remove('open');
      });
    }
  }

  // 入力欄の値をsongデータと同期
  syncInputsWithSong() {
    const titleInput = document.querySelector('#song-title-input');
    const artistInput = document.querySelector('#song-artist-input');
    const bpmInput = document.querySelector('#song-bpm-input');
    if (titleInput) titleInput.value = this.song.title || '';
    if (artistInput) artistInput.value = this.song.artist || '';
    if (bpmInput) bpmInput.value = this.song.bpm || 120;
  }

  // スタンプチップのアクティブ状態更新
  updateStampChipsActiveState() {
    document.querySelectorAll('.stamp-chip').forEach(chip => {
      const type = chip.dataset.stampType;
      if (this.stampManager.activeStampType === type) {
        chip.classList.add('active');
      } else {
        chip.classList.remove('active');
      }
    });
  }

  // 小節番号の自動リナンバリング
  renumberMeasures() {
    let count = 1;
    this.song.sections.forEach(sec => {
      sec.measures.forEach(m => {
        m.number = count++;
      });
    });
  }

  // --- アクティブセクション管理 & 再生連携 ---
  setActiveSection(sectionId) {
    if (!sectionId) return;
    const target = this.song.sections.find(s => s.id === sectionId);
    if (!target) return;
    if (this.activeSectionId === sectionId) return;

    this.activeSectionId = sectionId;
    this.updateActiveSectionUI();
  }

  getActiveSection() {
    let activeSec = this.song.sections.find(s => s.id === this.activeSectionId);
    if (!activeSec && this.song.sections.length > 0) {
      activeSec = this.song.sections[0];
      this.activeSectionId = activeSec.id;
    }
    return activeSec || null;
  }

  updateActiveSectionUI() {
    // セクションコンテナのクラス更新
    document.querySelectorAll('.section-container').forEach(el => {
      const secId = el.dataset.sectionId;
      const isActive = secId === this.activeSectionId;
      if (isActive) {
        el.classList.add('is-active-section');
      } else {
        el.classList.remove('is-active-section');
      }
    });

    this.updateSectionPlayButtons();
  }

  // 全セクションの再生 / 停止ボタン表示を同期更新
  updateSectionPlayButtons() {
    const isPlaying = this.playbackEngine.isPlaying;
    document.querySelectorAll('.section-play-btn').forEach(btn => {
      const secId = btn.dataset.sectionId;
      const isThisPlaying = isPlaying && this.currentPlayingSectionId === secId;

      if (isThisPlaying) {
        btn.classList.add('playing');
        btn.innerHTML = '■';
        btn.title = '再生を停止';
        btn.setAttribute('aria-label', '停止');
      } else {
        btn.classList.remove('playing');
        btn.innerHTML = '▶';
        btn.title = 'このセクションを再生';
        btn.setAttribute('aria-label', '再生');
      }
    });
  }

  // 指定したセクションを再生
  playSection(sectionId) {
    if (this.playbackEngine.isPlaying) {
      this.playbackEngine.stop();
    }
    const sec = this.song.sections.find(s => s.id === sectionId);
    if (!sec || !sec.measures || sec.measures.length === 0) return;

    this.activeSectionId = sectionId;
    this.currentPlayingSectionId = sectionId;
    this.playbackEngine.playSection(sec, this.song.bpm);
    this.updateSectionPlayButtons();
  }

  // 再生を停止
  stopPlayback() {
    this.playbackEngine.stop();
    this.currentPlayingSectionId = null;
    this.updateSectionPlayButtons();
  }

  // 後方互換性用
  playFromActiveSection(specificSectionId = null) {
    const targetId = specificSectionId || this.activeSectionId || this.song.sections[0]?.id;
    if (targetId) {
      this.playSection(targetId);
    }
  }

  // セクションの削除
  deleteSection(sectionId) {
    this.song.sections = this.song.sections.filter(s => s.id !== sectionId);
    if (this.activeSectionId === sectionId) {
      this.activeSectionId = this.song.sections[0]?.id || null;
    }
    this.renumberMeasures();
    this.saveStateAndRender();
    this.showToast('セクションを削除しました');
  }

  // セクションの複製
  duplicateSection(sectionId) {
    const sec = this.song.sections.find(s => s.id === sectionId);
    if (!sec) return;
    const cloned = JSON.parse(JSON.stringify(sec));
    cloned.id = generateId('sec');
    cloned.measures.forEach(m => {
      m.id = generateId('meas');
      if (m.stamps) m.stamps.forEach(st => st.id = generateId('st'));
      if (m.chords) m.chords.forEach(ch => ch.id = generateId('ch'));
    });
    const idx = this.song.sections.findIndex(s => s.id === sectionId);
    this.song.sections.splice(idx + 1, 0, cloned);
    this.activeSectionId = cloned.id; // 複製されたセクションをアクティブにする
    this.renumberMeasures();
    this.saveStateAndRender();
    this.showToast('セクションを複製しました');
  }

  // --- 小節のコピー＆ペースト ---
  copyMeasure(measure) {
    this.clipboardMeasure = JSON.parse(JSON.stringify(measure));
    this.showToast(`小節 #${measure.number} をコピーしました`);
    this.render(); // 貼付ボタンの有効化表示を即時反映
  }

  pasteMeasure(targetSectionId, targetMeasureId = null) {
    if (!this.clipboardMeasure) {
      this.showToast('クリップボードにコピーされた小節がありません');
      return;
    }
    const section = this.song.sections.find(s => s.id === targetSectionId);
    if (!section) return;

    const pasted = JSON.parse(JSON.stringify(this.clipboardMeasure));
    pasted.id = generateId('meas');
    if (pasted.chords) pasted.chords.forEach(c => c.id = generateId('ch'));
    if (pasted.stamps) pasted.stamps.forEach(st => st.id = generateId('st'));

    if (targetMeasureId) {
      const idx = section.measures.findIndex(m => m.id === targetMeasureId);
      if (idx !== -1) {
        section.measures.splice(idx + 1, 0, pasted);
      } else {
        section.measures.push(pasted);
      }
    } else {
      section.measures.push(pasted);
    }

    this.renumberMeasures();
    this.saveStateAndRender();
    this.showToast('コピーした小節を貼り付けました');
  }

  // --- 小節のドラッグ移動（同一セクション内およびセクション間） ---
  moveMeasure(sourceSecId, sourceMeasId, targetSecId, targetMeasId, placeBefore = false) {
    const srcSec = this.song.sections.find(s => s.id === sourceSecId);
    const tgtSec = this.song.sections.find(s => s.id === targetSecId);
    if (!srcSec || !tgtSec) return;

    const srcIdx = srcSec.measures.findIndex(m => m.id === sourceMeasId);
    if (srcIdx === -1) return;

    const [movingMeasure] = srcSec.measures.splice(srcIdx, 1);

    let tgtIdx = tgtSec.measures.findIndex(m => m.id === targetMeasId);
    if (tgtIdx === -1) {
      tgtSec.measures.push(movingMeasure);
    } else {
      const insertIdx = placeBefore ? tgtIdx : tgtIdx + 1;
      tgtSec.measures.splice(insertIdx, 0, movingMeasure);
    }

    this.renumberMeasures();
    this.saveStateAndRender();
    this.showToast(`小節を移動しました`);
  }

  // --- セクションのコピー＆ペースト ---
  copySection(section) {
    this.clipboardSection = JSON.parse(JSON.stringify(section));
    const secName = section.type === 'custom' ? (section.customName || 'カスタム') : section.type;
    this.showToast(`セクション「${secName}」をコピーしました`);
    this.render(); // 貼付ボタンの有効化表示を即時反映
  }

  pasteSection(targetSectionId = null) {
    if (!this.clipboardSection) {
      this.showToast('クリップボードにコピーされたセクションがありません');
      return;
    }
    const pasted = JSON.parse(JSON.stringify(this.clipboardSection));
    pasted.id = generateId('sec');
    pasted.measures.forEach(m => {
      m.id = generateId('meas');
      if (m.chords) m.chords.forEach(c => c.id = generateId('ch'));
      if (m.stamps) m.stamps.forEach(s => s.id = generateId('st'));
    });

    if (targetSectionId) {
      const idx = this.song.sections.findIndex(s => s.id === targetSectionId);
      if (idx !== -1) {
        this.song.sections.splice(idx + 1, 0, pasted);
      } else {
        this.song.sections.push(pasted);
      }
    } else {
      this.song.sections.push(pasted);
    }

    const secName = pasted.type === 'custom' ? (pasted.customName || 'カスタム') : pasted.type;
    this.renumberMeasures();
    this.saveStateAndRender();
    this.showToast(`セクション「${secName}」を貼り付けました`);
  }

  // --- セクションのドラッグ移動 ---
  moveSection(sourceSecId, targetSecId, placeBefore = false) {
    const srcIdx = this.song.sections.findIndex(s => s.id === sourceSecId);
    const tgtIdx = this.song.sections.findIndex(s => s.id === targetSecId);
    if (srcIdx === -1 || tgtIdx === -1 || srcIdx === tgtIdx) return;

    const [movingSec] = this.song.sections.splice(srcIdx, 1);
    const newTgtIdx = this.song.sections.findIndex(s => s.id === targetSecId);
    const insertIdx = placeBefore ? newTgtIdx : newTgtIdx + 1;
    this.song.sections.splice(insertIdx, 0, movingSec);

    this.renumberMeasures();
    this.saveStateAndRender();
    this.showToast(`セクションの順序を入れ替えました`);
  }

  // IDから小節を検索
  findMeasureById(measureId) {
    for (const sec of this.song.sections) {
      const found = sec.measures.find(m => m.id === measureId);
      if (found) return found;
    }
    return null;
  }

  // カラーピッカーポップオーバーの表示（セクション用 / 小節用）
  showColorPicker(anchorEl, onSelect, paletteType = 'measure') {
    // 既存のポップオーバーがあれば削除
    const existing = document.querySelector('.color-picker-popover');
    if (existing) existing.remove();

    const popover = document.createElement('div');
    popover.className = 'color-picker-popover';

    const header = document.createElement('div');
    header.className = 'color-picker-header';
    header.textContent = paletteType === 'section' ? 'セクションカラー選択' : '小節カラー選択';
    popover.appendChild(header);

    const swatches = document.createElement('div');
    swatches.className = 'palette-swatches';

    const palette = paletteType === 'section' ? SECTION_COLOR_PALETTE : MEASURE_COLOR_PALETTE;

    palette.forEach(item => {
      const swatch = document.createElement('div');
      swatch.className = 'swatch-item';
      swatch.style.backgroundColor = item.value === 'transparent' ? '#ffffff' : item.value;
      if (item.value === 'transparent') {
        swatch.style.border = '2px dashed #94a3b8';
      } else {
        swatch.style.borderColor = item.border || item.value;
      }
      swatch.title = item.name;
      swatch.addEventListener('click', (e) => {
        e.stopPropagation();
        onSelect(item.value);
        popover.remove();
      });
      swatches.appendChild(swatch);
    });

    popover.appendChild(swatches);

    // 位置計算
    const rect = anchorEl.getBoundingClientRect();
    popover.style.top = `${rect.bottom + window.scrollY + 6}px`;
    popover.style.left = `${rect.left + window.scrollX - 60}px`;

    document.body.appendChild(popover);

    // 外側クリックで閉じる
    const closeListener = (e) => {
      if (!popover.contains(e.target) && e.target !== anchorEl) {
        popover.remove();
        window.removeEventListener('click', closeListener);
      }
    };
    setTimeout(() => window.addEventListener('click', closeListener), 10);
  }

  // トースト通知の表示
  showToast(message) {
    let container = document.querySelector('.toast-container');
    if (!container) {
      container = document.createElement('div');
      container.className = 'toast-container';
      document.body.appendChild(container);
    }

    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    container.appendChild(toast);

    setTimeout(() => {
      toast.remove();
    }, 3200);
  }

  // 履歴管理 (Undo / Redo)
  pushHistory() {
    const currentJson = JSON.stringify(this.song);
    // 直前の履歴と完全に同一の場合は重複して履歴に追加しない
    if (this.history.length > 0 && this.historyIndex >= 0 && this.history[this.historyIndex] === currentJson) {
      this.updateUndoRedoButtons();
      return;
    }
    // 現在位置より先の履歴を破棄
    this.history = this.history.slice(0, this.historyIndex + 1);
    this.history.push(currentJson);
    this.historyIndex++;
    if (this.history.length > 100) {
      this.history.shift();
      this.historyIndex--;
    }
    this.updateUndoRedoButtons();
  }

  undo() {
    if (this.historyIndex > 0) {
      this.historyIndex--;
      this.song = JSON.parse(this.history[this.historyIndex]);
      if (!this.song.sections.some(s => s.id === this.activeSectionId)) {
        this.activeSectionId = this.song.sections[0]?.id || null;
      }
      this.saveState();
      this.syncInputsWithSong();
      this.render();
      this.updateUndoRedoButtons();
      this.showToast('元に戻しました (Undo)');
    }
  }

  redo() {
    if (this.historyIndex < this.history.length - 1) {
      this.historyIndex++;
      this.song = JSON.parse(this.history[this.historyIndex]);
      if (!this.song.sections.some(s => s.id === this.activeSectionId)) {
        this.activeSectionId = this.song.sections[0]?.id || null;
      }
      this.saveState();
      this.syncInputsWithSong();
      this.render();
      this.updateUndoRedoButtons();
      this.showToast('やり直しました (Redo)');
    }
  }

  // Undo / Redo ボタンの活性状態・ツールチップを更新
  updateUndoRedoButtons() {
    const undoBtn = document.querySelector('#undo-btn');
    const redoBtn = document.querySelector('#redo-btn');
    const canUndo = this.historyIndex > 0;
    const canRedo = this.historyIndex < this.history.length - 1;

    if (undoBtn) {
      undoBtn.disabled = !canUndo;
      undoBtn.title = canUndo ? '元に戻す (Ctrl+Z)' : '元に戻す (Ctrl+Z) - 変更なし';
      undoBtn.classList.toggle('disabled', !canUndo);
    }
    if (redoBtn) {
      redoBtn.disabled = !canRedo;
      redoBtn.title = canRedo ? 'やり直す (Ctrl+Y / Ctrl+Shift+Z)' : 'やり直す (Ctrl+Y / Ctrl+Shift+Z) - 履歴なし';
      redoBtn.classList.toggle('disabled', !canRedo);
    }
  }

  // 状態保存（LocalStorage）
  saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.song));
    } catch (e) {
      console.error('LocalStorage保存失敗:', e);
    }
  }

  // 状態保存＆再描画
  saveStateAndRender() {
    this.saveState();
    this.pushHistory();
    this.render();
  }

  // スタンプの高速更新（ドラッグ中の再描画抑制）
  renderFastStampUpdate(stamp) {
    const el = document.querySelector(`.stamp-item[data-stamp-id="${stamp.id}"]`);
    if (el) {
      el.style.left = `${stamp.x}px`;
      el.style.top = `${stamp.y}px`;
      el.style.width = `${stamp.width}px`;
      el.style.height = `${stamp.height}px`;
      el.style.transform = `rotate(${stamp.rotation || 0}deg)`;

      const textSpan = el.querySelector('.stamp-text');
      if (textSpan) {
        const fontSize = Math.max(9, Math.round((stamp.height || 26) * 0.52));
        textSpan.style.fontSize = `${fontSize}px`;
      }
    }
  }

  // キーボードショートカット
  initKeyboardShortcuts() {
    window.addEventListener('keydown', (e) => {
      const activeEl = document.activeElement;
      // Escapeキーで開いているモーダルをすべて閉じる
      if (e.key === 'Escape') {
        const openModal = document.querySelector('.modal-backdrop.open');
        if (openModal) {
          openModal.classList.remove('open');
          return;
        }
      }

      const isInput = activeEl && ['INPUT', 'TEXTAREA'].includes(activeEl.tagName);
      const isTabSlot = activeEl && activeEl.classList.contains('tab-slot-input');

      // Ctrl+S / Cmd+S で曲名保存
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
        e.preventDefault();
        this.saveCurrentProject();
        return;
      }

      // 通常のテキストフィールド（曲名入力等）にフォーカスがある時は、ブラウザ標準のテキストUndoを優先
      if (isInput && !isTabSlot) {
        return;
      }

      const isUndo = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z' && !e.shiftKey;
      const isRedo = ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'y') ||
                     ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z' && e.shiftKey);

      if (isUndo) {
        e.preventDefault();
        if (isTabSlot) activeEl.blur();
        this.undo();
      } else if (isRedo) {
        e.preventDefault();
        if (isTabSlot) activeEl.blur();
        this.redo();
      } else if (e.code === 'Space' && !isInput) {
        console.log('[app.js] Space key pressed, activeEl:', activeEl?.tagName, 'activeSectionId:', this.activeSectionId, 'isPlaying:', this.playbackEngine.isPlaying);
        // スペースキーで再生/停止（アクティブセクション）
        e.preventDefault();
        if (activeEl && typeof activeEl.blur === 'function') {
          activeEl.blur();
        }
        if (this.playbackEngine.isPlaying) {
          this.stopPlayback();
        } else {
          const targetId = this.activeSectionId || this.song.sections[0]?.id;
          console.log('[app.js] playing targetId:', targetId);
          if (targetId) {
            this.playSection(targetId);
          }
        }
      }
    });
  }

  // 保存先フォルダ表示の更新
  async refreshFolderDisplay() {
    try {
      const textEl = document.querySelector('#current-folder-text');
      const badgeEl = document.querySelector('#current-folder-badge');
      const openFolderBtn = document.querySelector('#open-folder-btn');

      if (isAndroidApp()) {
        if (textEl) textEl.textContent = 'Documents/TabMaker';
        if (badgeEl) badgeEl.title = 'Androidの保存先: Documents/TabMaker (タップで設定)';
        if (openFolderBtn) {
          openFolderBtn.innerHTML = '📤 保存・共有設定';
          openFolderBtn.title = '端末内のDocuments/TabMakerフォルダに保存されます。タップで設定を確認';
        }
        return;
      }

      if (openFolderBtn) {
        openFolderBtn.innerHTML = '📁 出力先フォルダ';
        openFolderBtn.title = '出力されたファイルが保存されているPCフォルダ（Documents/TabMaker/projects）を開く';
      }

      const settings = await getExportSettings();
      if (textEl && settings.outputDir) {
        // パスの末尾フォルダ名または分かりやすい名前を表示
        const dir = settings.outputDir;
        let displayName = dir.split(/[\\/]/).filter(Boolean).pop() || dir;
        if (dir.toLowerCase().includes('tabmaker') || dir.toLowerCase().endsWith('projects')) {
          displayName = 'TabMaker projects';
        } else if (dir.toLowerCase().includes('download')) {
          displayName = 'ダウンロード';
        } else if (dir.toLowerCase().includes('desktop')) {
          displayName = 'デスクトップ';
        } else if (dir.toLowerCase().includes('document')) {
          displayName = 'ドキュメント';
        } else if (dir.endsWith('output')) {
          displayName = 'アプリ内 output';
        }

        textEl.textContent = displayName;
        if (badgeEl) badgeEl.title = `現在の保存先: ${dir} (クリックで変更)`;
      }
    } catch (e) {
      console.error('フォルダ表示更新エラー:', e);
    }
  }

  // フォルダ設定モーダルを開く際の入力同期
  async syncFolderModalInputs() {
    try {
      const androidSection = document.querySelector('#folder-modal-android-section');
      const pcSection = document.querySelector('#folder-modal-pc-section');
      const titleEl = document.querySelector('#folder-settings-modal-title');

      if (isAndroidApp()) {
        if (titleEl) titleEl.textContent = '📂 Android での保存・共有設定';
        if (androidSection) androidSection.style.display = 'block';
        if (pcSection) pcSection.style.display = 'none';

        const autoShareCheck = document.querySelector('#android-auto-share-checkbox');
        const androidSettings = getAndroidExportSettings();
        if (autoShareCheck) {
          autoShareCheck.checked = androidSettings.autoShare !== false;
          autoShareCheck.onchange = () => {
            saveAndroidExportSettings({ autoShare: autoShareCheck.checked });
            this.showToast(autoShareCheck.checked ? '自動共有メニューを有効にしました' : '自動共有メニューを無効にしました');
          };
        }
        return;
      }

      if (titleEl) titleEl.textContent = '📂 スプレッドシート出力先のフォルダ設定';
      if (androidSection) androidSection.style.display = 'none';
      if (pcSection) pcSection.style.display = 'block';

      const settings = await getExportSettings();
      const manualInput = document.querySelector('#manual-folder-input');
      if (manualInput) {
        manualInput.value = settings.outputDir || '';
      }

      // プリセットパスの表示更新とアクティブ状態反映
      if (settings.presetDirs) {
        for (const [key, pathVal] of Object.entries(settings.presetDirs)) {
          const pathEl = document.querySelector(`#preset-path-${key}`);
          if (pathEl) pathEl.textContent = pathVal;

          const btn = document.querySelector(`.preset-folder-btn[data-preset="${key}"]`);
          if (btn) {
            if (settings.outputDir === pathVal) {
              btn.classList.add('active');
            } else {
              btn.classList.remove('active');
            }
          }
        }
      }
    } catch (e) {
      console.error('フォルダ設定同期エラー:', e);
    }
  }

  // 印刷設定モーダルを開く（保存された設定、またはデフォルトのA4縦を反映）
  openPrintSettingsModal() {
    const printModal = document.querySelector('#print-settings-modal');
    if (!printModal) return;

    const settings = getSavedPrintSettings();

    // 向きラジオ（デフォルト: A4縦）
    const isPortrait = settings.orientation !== 'landscape';
    const portraitCard = printModal.querySelector('#card-orient-portrait');
    const landscapeCard = printModal.querySelector('#card-orient-landscape');
    const portraitRadio = printModal.querySelector('input[value="portrait"]');
    const landscapeRadio = printModal.querySelector('input[value="landscape"]');

    if (isPortrait) {
      if (portraitCard) portraitCard.classList.add('active');
      if (landscapeCard) landscapeCard.classList.remove('active');
      if (portraitRadio) portraitRadio.checked = true;
    } else {
      if (landscapeCard) landscapeCard.classList.add('active');
      if (portraitCard) portraitCard.classList.remove('active');
      if (landscapeRadio) landscapeRadio.checked = true;
    }

    // セレクトボックス
    const pageSizeSelect = printModal.querySelector('#print-page-size-select');
    if (pageSizeSelect) pageSizeSelect.value = settings.pageSize || 'A4';

    const measuresSelect = printModal.querySelector('#print-measures-per-row-select');
    if (measuresSelect) measuresSelect.value = String(settings.measuresPerRow || 4);

    const marginSelect = printModal.querySelector('#print-margin-select');
    if (marginSelect) marginSelect.value = settings.margin || '10mm';

    // チェックボックス
    const headerCheck = printModal.querySelector('#print-opt-header');
    if (headerCheck) headerCheck.checked = settings.showPrintHeader !== false;

    const footerCheck = printModal.querySelector('#print-opt-footer');
    if (footerCheck) footerCheck.checked = settings.showSectionFooter !== false;

    printModal.classList.add('open');
  }

  // エクスポート完了モーダルの表示とボタンの紐付け
  showExportSuccessModal(result) {
    const modal = document.querySelector('#export-success-modal');
    if (!modal) return;

    const filenameEl = document.querySelector('#export-modal-filename');
    const pathEl = document.querySelector('#export-modal-path');
    const openFolderBtn = document.querySelector('#modal-open-folder-btn');
    const openDriveBtn = document.querySelector('#modal-open-drive-btn');
    const directDlLink = document.querySelector('#modal-direct-download-link');
    const closeBtn = modal.querySelector('.modal-close-btn');

    // Android/PC 表示切替用
    const actionsAndroid = document.querySelector('#export-actions-android');
    const actionsPc = document.querySelector('#export-actions-pc');
    const androidShareBtn = document.querySelector('#modal-android-share-btn');
    const androidSettingsBtn = document.querySelector('#modal-android-settings-btn');
    const guideText = document.querySelector('#export-modal-guide-text');

    if (filenameEl) filenameEl.textContent = result.filename;
    if (pathEl) {
      if (result.isAndroid) {
        pathEl.innerHTML = `保存先: <strong style="color: #38bdf8;">内部ストレージ &gt; Documents &gt; TabMaker</strong>`;
      } else if (result.filePath) {
        pathEl.innerHTML = `保存先: <strong style="color: #38bdf8;">${result.filePath}</strong>`;
      } else {
        pathEl.textContent = `ブラウザのダウンロードフォルダに保存されました`;
      }
    }

    if (isAndroidApp()) {
      if (actionsAndroid) actionsAndroid.style.display = 'flex';
      if (actionsPc) actionsPc.style.display = 'none';
      if (guideText) {
        guideText.textContent = '※ 「共有する」からGoogleドライブにアップロードすると、Googleスプレッドシートとしてそのまま開き、バンドメンバーと共有・共同編集できます。';
      }

      if (androidShareBtn) {
        androidShareBtn.onclick = async () => {
          await shareExportedFile(result.fileUri || result.filePath, result.filename, this.song?.title);
        };
      }
      if (androidSettingsBtn) {
        androidSettingsBtn.onclick = () => {
          modal.classList.remove('open');
          this.syncFolderModalInputs();
          const fModal = document.querySelector('#folder-settings-modal');
          if (fModal) fModal.classList.add('open');
        };
      }
    } else {
      if (actionsAndroid) actionsAndroid.style.display = 'none';
      if (actionsPc) actionsPc.style.display = 'flex';

      if (openFolderBtn) {
        openFolderBtn.onclick = () => {
          openExportFolder(result.filePath || null);
          this.showToast('エクスプローラーで保存先フォルダを開きました');
        };
      }

      const selectFolderBtn = document.querySelector('#modal-select-folder-btn');
      if (selectFolderBtn) {
        selectFolderBtn.onclick = () => {
          modal.classList.remove('open');
          this.syncFolderModalInputs();
          const fModal = document.querySelector('#folder-settings-modal');
          if (fModal) fModal.classList.add('open');
        };
      }

      if (openDriveBtn) {
        openDriveBtn.onclick = () => {
          window.open('https://drive.google.com/drive/my-drive', '_blank');
        };
      }

      if (directDlLink && result.blobUrl) {
        directDlLink.href = result.blobUrl;
        directDlLink.download = result.filename;
      }
    }

    if (closeBtn) {
      closeBtn.onclick = () => modal.classList.remove('open');
    }

    modal.onclick = (e) => {
      if (e.target === modal) modal.classList.remove('open');
    };

    modal.classList.add('open');
  }

  // 楽譜メインキャンバスの描画
  render() {
    const canvas = document.querySelector('#main-canvas');
    if (!canvas) return;
    canvas.innerHTML = '';

    // 印刷用ヘッダー
    const printHeader = document.createElement('div');
    printHeader.className = 'print-header';
    printHeader.innerHTML = `
      <div class="print-title">🎸 ${this.song.title || '無題のタブ譜'}</div>
      <div class="print-meta">アーティスト: ${this.song.artist || 'TabMaker'} | BPM: ${this.song.bpm || 120} | 拍子: ${this.song.timeSignature || '4/4'}</div>
    `;
    canvas.appendChild(printHeader);

    // 各セクションの描画
    this.song.sections.forEach(section => {
      const sectionView = new SectionView(this, section);
      canvas.appendChild(sectionView.render());
    });

    // キャンバス下部のセクション追加・貼付フッターバー
    const footerBar = document.createElement('div');
    footerBar.className = 'canvas-footer-bar';

    const addSecBtn = document.createElement('button');
    addSecBtn.className = 'btn btn-primary';
    addSecBtn.innerHTML = '+セクション';
    addSecBtn.addEventListener('click', () => {
      const newSec = createNewSection('aメロ', { measureCount: 4 });
      this.song.sections.push(newSec);
      this.activeSectionId = newSec.id;
      this.renumberMeasures();
      this.saveStateAndRender();
      this.showToast('新しいセクションを追加しました');
    });
    footerBar.appendChild(addSecBtn);

    const addChordSecBtn = document.createElement('button');
    addChordSecBtn.className = 'btn btn-primary';
    addChordSecBtn.innerHTML = '+コードセクション';
    addChordSecBtn.addEventListener('click', () => {
      const newSec = createNewSection('aメロ', { isChordOnly: true, measureCount: 4 });
      this.song.sections.push(newSec);
      this.activeSectionId = newSec.id;
      this.renumberMeasures();
      this.saveStateAndRender();
      this.showToast('コードセクションを追加しました');
    });
    footerBar.appendChild(addChordSecBtn);

    const addCompactSecBtn = document.createElement('button');
    addCompactSecBtn.className = 'btn btn-primary';
    addCompactSecBtn.innerHTML = '+省略セクション';
    addCompactSecBtn.addEventListener('click', () => {
      const newSec = createNewSection('aメロ', { isCompact: true });
      this.song.sections.push(newSec);
      this.activeSectionId = newSec.id;
      this.renumberMeasures();
      this.saveStateAndRender();
      this.showToast('省略セクションを追加しました');
    });
    footerBar.appendChild(addCompactSecBtn);
    canvas.appendChild(footerBar);

    // アクティブセクションのハイライトと再生ボタン表示を反映
    this.updateActiveSectionUI();
    this.updateUndoRedoButtons();
  }

  // --- プロジェクト保存・一覧管理機能 ---

  // 保存済みプロジェクト一覧の取得
  getSavedProjects() {
    try {
      const raw = localStorage.getItem(STORAGE_PROJECTS_INDEX_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      console.error('プロジェクト一覧の読み込み失敗:', e);
      return [];
    }
  }

  // 現在の曲名でプロジェクトを保存
  async saveCurrentProject(options = {}) {
    const { silentToast = false } = options;
    let title = (this.song.title || '').trim();
    if (!title) {
      const input = prompt('曲名を入力してください:', 'マイタブ譜');
      if (input === null) return;
      title = input.trim() || '無題のタブ譜';
      this.song.title = title;
      const titleInput = document.querySelector('#song-title-input');
      if (titleInput) titleInput.value = title;
    }

    if (!this.song.projectId) {
      this.song.projectId = generateId('proj');
    }

    // 小節数、セクション数の集計
    let measureCount = 0;
    (this.song.sections || []).forEach(s => measureCount += (s.measures || []).length);
    const sectionCount = (this.song.sections || []).length;

    const projectMeta = {
      id: this.song.projectId,
      title: title,
      artist: this.song.artist || 'TabMaker',
      bpm: this.song.bpm || 120,
      measureCount: measureCount,
      sectionCount: sectionCount,
      updatedAt: new Date().toISOString()
    };

    // 1. インデックスの更新（同一IDまたは同一曲名なら更新、なければ先頭追加）
    let projects = this.getSavedProjects();
    const existingIdx = projects.findIndex(p => p.id === this.song.projectId || p.title === title);
    if (existingIdx !== -1) {
      this.song.projectId = projects[existingIdx].id;
      projectMeta.id = this.song.projectId;
      projects[existingIdx] = projectMeta;
    } else {
      projects.unshift(projectMeta);
    }

    try {
      localStorage.setItem(STORAGE_PROJECTS_INDEX_KEY, JSON.stringify(projects));
      localStorage.setItem(`${STORAGE_PROJECT_DATA_PREFIX}${this.song.projectId}`, JSON.stringify(this.song));
      this.saveState();
    } catch (e) {
      console.error('LocalStorageプロジェクト保存失敗:', e);
    }

    // 2. PCローカルフォルダおよびファイルへの保存
    const jsonContent = JSON.stringify(this.song, null, 2);
    const safeTitle = title.replace(/[/\\?%*:|"<>]/g, '_');
    const filename = `${safeTitle}.tabmaker`;

    try {
      const res = await fetch('/api/save-project', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ filename, jsonContent })
      });
      if (!silentToast) {
        if (res.ok) {
          const data = await res.json();
          this.showToast(`プロジェクト「${title}」を保存しました\n📁 ${data.filename || filename}`);
        } else {
          this.showToast(`曲名「${title}」でプロジェクトを保存しました`);
        }
      }
    } catch (err) {
      // サーバー未起動時（オフライン時等）は無視
      if (!silentToast) {
        this.showToast(`曲名「${title}」でプロジェクトを保存しました`);
      }
    }

    this.renderProjectsList();
  }

  // 現在開いているプロジェクト（または指定したプロジェクト）を複製して開く
  async duplicateCurrentProject(sourceSongData = null) {
    const targetSong = sourceSongData || this.song;
    if (!targetSong) return;

    // 現在のプロジェクトを複製する場合、複製元もプロジェクト一覧に残るよう事前保存しておく
    if (!sourceSongData && this.song) {
      if (!this.song.title || !this.song.title.trim()) {
        this.song.title = '無題のタブ譜';
      }
      await this.saveCurrentProject({ silentToast: true });
    }

    // ディープコピーとID再生成
    const cloned = JSON.parse(JSON.stringify(targetSong));
    cloned.projectId = generateId('proj');
    (cloned.sections || []).forEach(sec => {
      sec.id = generateId('sec');
      (sec.measures || []).forEach(m => {
        m.id = generateId('meas');
        if (m.chords) m.chords.forEach(c => c.id = generateId('ch'));
        if (m.stamps) m.stamps.forEach(st => st.id = generateId('st'));
      });
    });

    // 重複しない複製曲名を生成
    const rawTitle = (targetSong.title || '無題のタブ譜').trim();
    const baseTitle = rawTitle.replace(/\s*\(コピー(?:\s*\d+)?\)$/, '');
    const projects = this.getSavedProjects();
    const existingTitles = new Set(projects.map(p => p.title));
    existingTitles.add(rawTitle);

    let newTitle = `${baseTitle} (コピー)`;
    let copyIndex = 2;
    while (existingTitles.has(newTitle)) {
      newTitle = `${baseTitle} (コピー ${copyIndex})`;
      copyIndex++;
    }
    cloned.title = newTitle;

    // 複製したプロジェクトを現在の曲として開く
    this.song = cloned;
    this.activeSectionId = this.song.sections?.[0]?.id || null;
    this.history = [];
    this.historyIndex = -1;
    this.pushHistory();
    this.syncInputsWithSong();
    await this.saveCurrentProject({ silentToast: true });
    this.render();

    const modal = document.querySelector('#project-manager-modal');
    if (modal) modal.classList.remove('open');

    this.showToast(`プロジェクトを「${newTitle}」として複製して開きました`);
  }

  // 保存済みプロジェクトIDを指定して複製して開く
  async duplicateProject(projectId) {
    try {
      const raw = localStorage.getItem(`${STORAGE_PROJECT_DATA_PREFIX}${projectId}`);
      if (!raw) {
        this.showToast('複製元のプロジェクトデータが見つかりませんでした');
        return;
      }
      const sourceSong = JSON.parse(raw);
      await this.duplicateCurrentProject(sourceSong);
    } catch (e) {
      console.error('プロジェクト複製失敗:', e);
      this.showToast('プロジェクトの複製に失敗しました');
    }
  }

  // プロジェクトを開く
  openProject(projectId) {
    try {
      const raw = localStorage.getItem(`${STORAGE_PROJECT_DATA_PREFIX}${projectId}`);
      if (!raw) {
        this.showToast('プロジェクトデータが見つかりませんでした');
        return;
      }
      this.song = JSON.parse(raw);
      this.activeSectionId = this.song.sections?.[0]?.id || null;
      this.history = [];
      this.historyIndex = -1;
      this.pushHistory();
      this.saveState();
      this.syncInputsWithSong();
      this.render();

      const modal = document.querySelector('#project-manager-modal');
      if (modal) modal.classList.remove('open');

      this.showToast(`プロジェクト「${this.song.title}」を開きました`);
    } catch (e) {
      console.error('プロジェクトオープン失敗:', e);
      this.showToast('プロジェクトの読み込みに失敗しました');
    }
  }

  // プロジェクトを削除
  deleteProject(projectId) {
    let projects = this.getSavedProjects();
    const target = projects.find(p => p.id === projectId);
    const name = target ? target.title : 'このプロジェクト';

    if (!confirm(`プロジェクト「${name}」を削除しますか？`)) {
      return;
    }

    projects = projects.filter(p => p.id !== projectId);
    try {
      localStorage.setItem(STORAGE_PROJECTS_INDEX_KEY, JSON.stringify(projects));
      localStorage.removeItem(`${STORAGE_PROJECT_DATA_PREFIX}${projectId}`);
    } catch (e) {
      console.error('プロジェクト削除失敗:', e);
    }

    this.showToast(`プロジェクト「${name}」を削除しました`);
    this.renderProjectsList();
  }

  // プロジェクトファイルをダウンロード
  downloadProjectFile(songData = null) {
    const data = songData || this.song;
    const title = data.title || '無題のタブ譜';
    const safeTitle = title.replace(/[/\\?%*:|"<>]/g, '_');
    const filename = `${safeTitle}.tabmaker`;

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 100);
    this.showToast(`「${filename}」を書き出しました`);
  }

  // ファイルからプロジェクトを読み込み
  importProjectFromFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const parsed = JSON.parse(e.target.result);
        const songData = parsed.song || parsed;

        if (!songData.sections || !Array.isArray(songData.sections)) {
          alert('有効なTabMakerプロジェクトファイルではありません。');
          return;
        }

        this.song = songData;
        this.song.projectId = generateId('proj');
        this.activeSectionId = this.song.sections?.[0]?.id || null;
        this.history = [];
        this.historyIndex = -1;
        this.pushHistory();
        this.saveCurrentProject();
        this.syncInputsWithSong();
        this.render();

        const modal = document.querySelector('#project-manager-modal');
        if (modal) modal.classList.remove('open');

        this.showToast(`ファイル「${file.name}」を読み込みました`);
      } catch (err) {
        console.error('ファイルインポートエラー:', err);
        alert('ファイルの読み込みに失敗しました。正しいJSON/tabmakerファイルか確認してください。');
      }
    };
    reader.readAsText(file);
  }

  // プロジェクト管理モーダルを開く
  openProjectManagerModal() {
    const modal = document.querySelector('#project-manager-modal');
    if (!modal) return;
    this.renderProjectsList();
    modal.classList.add('open');
  }

  // プロジェクト一覧の描画
  renderProjectsList() {
    const container = document.querySelector('#projects-list-container');
    const countBadge = document.querySelector('#project-list-count');
    if (!container) return;

    const projects = this.getSavedProjects();
    if (countBadge) countBadge.textContent = `${projects.length}件`;

    container.innerHTML = '';

    if (projects.length === 0) {
      container.innerHTML = `
        <div class="project-empty-state">
          🎸 まだ保存されたプロジェクトはありません。<br>
          曲名を入力して上の<strong>「💾 現在の曲を保存」</strong>ボタンを押すと保存されます。
        </div>
      `;
      return;
    }

    projects.forEach(p => {
      const card = document.createElement('div');
      card.className = 'project-card';
      const isCurrent = this.song && (this.song.projectId === p.id || this.song.title === p.title);
      if (isCurrent) {
        card.classList.add('is-current');
      }

      // 日時フォーマット
      let dateStr = '';
      try {
        const d = new Date(p.updatedAt);
        dateStr = `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2, '0')}/${d.getDate().toString().padStart(2, '0')} ${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`;
      } catch (e) {
        dateStr = p.updatedAt || '';
      }

      card.innerHTML = `
        <div class="project-info">
          <div class="project-title-row">
            <span class="project-title-name">${escapeHtml(p.title)}</span>
            ${isCurrent ? '<span class="project-current-tag">編集中</span>' : ''}
          </div>
          <div class="project-meta-row">
            <span>👤 ${escapeHtml(p.artist || 'TabMaker')}</span>
            <span>⏱️ BPM ${p.bpm || 120}</span>
            <span>🎵 ${p.measureCount || 0}小節 (${p.sectionCount || 0}セクション)</span>
            <span>🕒 ${dateStr}</span>
          </div>
        </div>
        <div class="project-card-actions">
          <button class="btn btn-primary btn-sm btn-open-proj" title="このプロジェクトを開く">
            開く
          </button>
          <button class="btn btn-secondary btn-xs btn-dup-proj" title="このプロジェクトを複製して開く">
            📑
          </button>
          <button class="btn btn-secondary btn-xs btn-export-proj" title="ファイル (.tabmaker) としてPCに書き出し">
            💾
          </button>
          <button class="btn btn-secondary btn-xs btn-del-proj" title="このプロジェクトを削除" style="color: #ef4444;">
            🗑️
          </button>
        </div>
      `;

      card.querySelector('.btn-open-proj').addEventListener('click', () => {
        this.openProject(p.id);
      });

      card.querySelector('.btn-dup-proj').addEventListener('click', () => {
        this.duplicateProject(p.id);
      });

      card.querySelector('.btn-export-proj').addEventListener('click', () => {
        const raw = localStorage.getItem(`${STORAGE_PROJECT_DATA_PREFIX}${p.id}`);
        if (raw) {
          this.downloadProjectFile(JSON.parse(raw));
        } else {
          this.showToast('データが見つかりません');
        }
      });

      card.querySelector('.btn-del-proj').addEventListener('click', () => {
        this.deleteProject(p.id);
      });

      container.appendChild(card);
    });
  }

  /**
   * コード入力・編集専用モーダルを開く
   */
  openChordEditModal({ title = '🎵 コードの編集', currentText = '', showDelete = true, onSave, onDelete }) {
    const modal = document.querySelector('#chord-edit-modal');
    if (!modal) return;

    const titleEl = document.querySelector('#chord-modal-title');
    const inputEl = document.querySelector('#chord-edit-input');
    const delBtn = document.querySelector('#btn-delete-chord');
    const saveBtn = document.querySelector('#btn-save-chord');
    const cancelBtn = document.querySelector('#btn-cancel-chord');
    const closeBtn = document.querySelector('#btn-close-chord-modal');
    const quickBtns = modal.querySelectorAll('.quick-chord-btn');

    if (titleEl) titleEl.textContent = title;
    if (inputEl) {
      inputEl.value = currentText;
    }
    if (delBtn) {
      delBtn.style.display = showDelete ? 'inline-block' : 'none';
    }

    const cleanup = () => {
      saveBtn.onclick = null;
      cancelBtn.onclick = null;
      closeBtn.onclick = null;
      delBtn.onclick = null;
      if (inputEl) inputEl.onkeydown = null;
      modal.onclick = null;
      quickBtns.forEach(btn => { btn.onclick = null; });
    };

    const closeModal = () => {
      modal.classList.remove('open');
      cleanup();
    };

    const handleSave = () => {
      const val = inputEl ? inputEl.value.trim() : '';
      closeModal();
      if (val !== '' && onSave) {
        onSave(val);
      } else if (val === '' && showDelete && onDelete) {
        // 空白で保存された場合は安全に削除扱いにする
        onDelete();
      }
    };

    const handleDelete = () => {
      closeModal();
      if (onDelete) onDelete();
    };

    const onKeyDown = (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleSave();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        closeModal();
      }
    };

    const onQuickClick = (e) => {
      if (inputEl) {
        inputEl.value = e.target.textContent.trim();
        inputEl.focus();
      }
    };

    const onBackdropClick = (e) => {
      if (e.target === modal) {
        closeModal();
      }
    };

    saveBtn.onclick = handleSave;
    cancelBtn.onclick = closeModal;
    closeBtn.onclick = closeModal;
    delBtn.onclick = handleDelete;
    if (inputEl) inputEl.onkeydown = onKeyDown;
    modal.onclick = onBackdropClick;
    quickBtns.forEach(btn => { btn.onclick = onQuickClick; });

    modal.classList.add('open');
    setTimeout(() => {
      if (inputEl) {
        inputEl.focus();
        inputEl.select();
      }
    }, 100);
  }
}

