/**
 * PDF / 印刷 出力モジュール
 * ブラウザ標準のベクター印刷機能を用いて、高画質なA4タブ譜PDFを出力します。
 * デフォルトはA4の縦向き（Portrait）。
 */

import { registerPlugin } from '@capacitor/core';
import { isAndroidApp } from '../utils/platform.js';

const NativePrint = registerPlugin('NativePrint');

const STORAGE_PRINT_SETTINGS_KEY = 'tabmaker_print_settings';

export const DEFAULT_PRINT_SETTINGS = {
  orientation: 'portrait',       // 'portrait' (縦) または 'landscape' (横) ★デフォルトはA4縦
  pageSize: 'A4',               // 'A4', 'B5', 'Letter'
  measuresPerRow: 4,            // 2, 3, 4
  margin: '10mm',               // '10mm', '6mm', '0mm'
  showPrintHeader: true,        // 曲名・アーティスト等のヘッダー表示
  showSectionFooter: true       // セクション末尾の備考テキスト表示
};

// 保存された印刷設定を取得（未設定時はデフォルト）
export function getSavedPrintSettings() {
  try {
    const raw = localStorage.getItem(STORAGE_PRINT_SETTINGS_KEY);
    if (raw) {
      return { ...DEFAULT_PRINT_SETTINGS, ...JSON.parse(raw) };
    }
  } catch (e) {
    console.error('印刷設定の読み込みに失敗しました:', e);
  }
  return { ...DEFAULT_PRINT_SETTINGS };
}

// 印刷設定の保存
export function savePrintSettings(settings) {
  try {
    localStorage.setItem(STORAGE_PRINT_SETTINGS_KEY, JSON.stringify(settings));
  } catch (e) {
    console.error('印刷設定の保存に失敗しました:', e);
  }
}

// 指定した印刷設定を適用してPDF印刷ダイアログを起動
export async function exportToPdf(customOptions = {}) {
  const settings = { ...getSavedPrintSettings(), ...customOptions };

  // 動的印刷オーバーライドスタイルの生成・適用
  let styleEl = document.querySelector('#tabmaker-dynamic-print-style');
  if (!styleEl) {
    styleEl = document.createElement('style');
    styleEl.id = 'tabmaker-dynamic-print-style';
    document.head.appendChild(styleEl);
  }

  const {
    orientation = 'portrait',
    pageSize = 'A4',
    measuresPerRow = 4,
    margin = '10mm',
    showPrintHeader = true,
    showSectionFooter = true
  } = settings;

  styleEl.textContent = `
    @media print {
      @page {
        size: ${pageSize} ${orientation} !important;
        margin: ${margin} !important;
      }
      .measures-grid {
        grid-template-columns: repeat(${measuresPerRow}, minmax(0, 1fr)) !important;
        width: 100% !important;
        max-width: 100% !important;
      }
      ${!showPrintHeader ? '.print-header { display: none !important; }' : ''}
      ${!showSectionFooter ? '.section-footer, .section-compact-footer-input { display: none !important; }' : ''}
    }
  `;

  // 印刷タイトルを一時的に設定（PDF保存時のファイル名に反映される）
  const originalTitle = document.title;
  const songTitleEl = document.querySelector('#song-title-input');
  const songTitle = (songTitleEl && songTitleEl.value) ? songTitleEl.value : 'TabMaker';
  document.title = `${songTitle} - TabMaker`;

  // 印刷プレビューモードを適用
  document.body.classList.add('printing-mode');

  let cleanedUp = false;
  const cleanup = () => {
    if (cleanedUp) return;
    cleanedUp = true;
    document.body.classList.remove('printing-mode');
    document.title = originalTitle;
    window.removeEventListener('focus', onFocusReturn);
  };

  const onFocusReturn = () => {
    // 印刷ダイアログからアプリ画面に復帰した時にモードを解除
    setTimeout(cleanup, 1200);
  };

  if (isAndroidApp()) {
    try {
      window.addEventListener('focus', onFocusReturn, { once: true });
      // 万が一focusが発火しない場合でも十分な時間後に安全解除（30秒）
      setTimeout(cleanup, 30000);

      // Androidネイティブの印刷（PDF形式で保存）ダイアログを起動
      await NativePrint.print({
        title: `${songTitle} - TabMaker`,
        orientation: orientation
      });

      return { success: true };
    } catch (e) {
      cleanup();
      console.error('NativePrint呼び出し失敗:', e);
      throw new Error(e.message || '印刷ダイアログの起動に失敗しました');
    }
  } else {
    // ブラウザ / PC (Windows) 環境の印刷ダイアログ
    window.print();
    window.addEventListener('afterprint', cleanup, { once: true });
    setTimeout(cleanup, 4000);
    return { success: true };
  }
}

