import { Capacitor } from '@capacitor/core';

/**
 * Androidアプリ（Capacitorネイティブ）として実行されているかを判定
 */
export function isAndroidApp() {
  try {
    return Capacitor.isNativePlatform() && Capacitor.getPlatform() === 'android';
  } catch (e) {
    return false;
  }
}

/**
 * ネイティブアプリ（Android等）として実行されているかを判定
 */
export function isNativePlatform() {
  try {
    return Capacitor.isNativePlatform();
  } catch (e) {
    return false;
  }
}

const ANDROID_SETTINGS_KEY = 'tabmaker_android_export_settings';

export const DEFAULT_ANDROID_SETTINGS = {
  storageLocation: 'documents', // 'documents' (Documents/TabMaker)
  autoShare: true               // エクスポート後に自動で共有メニューを開く
};

/**
 * Android用エクスポート設定を取得
 */
export function getAndroidExportSettings() {
  try {
    const raw = localStorage.getItem(ANDROID_SETTINGS_KEY);
    if (raw) {
      return { ...DEFAULT_ANDROID_SETTINGS, ...JSON.parse(raw) };
    }
  } catch (e) {
    console.warn('Android設定取得失敗:', e);
  }
  return { ...DEFAULT_ANDROID_SETTINGS };
}

/**
 * Android用エクスポート設定を保存
 */
export function saveAndroidExportSettings(settings) {
  try {
    const merged = { ...getAndroidExportSettings(), ...settings };
    localStorage.setItem(ANDROID_SETTINGS_KEY, JSON.stringify(merged));
    return merged;
  } catch (e) {
    console.error('Android設定保存失敗:', e);
    return null;
  }
}
