/**
 * Googleスプレッドシート互換の Excel (.xlsx) 出力モジュール
 * ExcelJS を用いて、サンプルファイル同様の美しい罫線・背景色・配置を持ったスプレッドシートを生成します。
 */
import ExcelJS from 'exceljs';
import JSZip from 'jszip';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { Share } from '@capacitor/share';
import { renderStampToPng } from './stampImageRenderer.js';
import { isAndroidApp, getAndroidExportSettings } from '../utils/platform.js';

export function buildExcelWorkbook(song) {
  const workbook = new ExcelJS.Workbook();
  workbook.creator = 'TabMaker';
  workbook.lastModifiedBy = 'TabMaker';
  workbook.created = new Date();
  workbook.modified = new Date();

  const sheet = workbook.addWorksheet(song.title || 'タブ譜面', {
    views: [{ showGridLines: false }]
  });

  // フォントとボーダースタイル定義
  const headerFont = { name: 'Arial', size: 14, bold: true, color: { argb: 'FFFFFFFF' } };
  const sectionTitleFont = { name: 'Arial', size: 12, bold: true, color: { argb: 'FFFFFFFF' } };
  const chordFont = { name: 'Arial', size: 10, bold: true, color: { argb: 'FF1E293B' } };
  const tabFont = { name: 'Consolas', size: 11, bold: true, color: { argb: 'FF0F172A' } };
  const stringLabelFont = { name: 'Arial', size: 9, bold: true, color: { argb: 'FF64748B' } };
  const stampFont = { name: 'Arial', size: 10, bold: true, color: { argb: 'FF0284C7' } };
  const chokeFont = { name: 'Arial', size: 11, bold: true, color: { argb: 'FFEF4444' } };
  const textStampFont = { name: 'Arial', size: 9, bold: true, color: { argb: 'FF1E293B' } };

  // 弦の横線用ボーダー
  const tabLineBorder = {
    top: { style: 'thin', color: { argb: 'FF64748B' } },
    bottom: { style: 'thin', color: { argb: 'FF64748B' } }
  };
  const barLineBorderRight = {
    right: { style: 'medium', color: { argb: 'FF0F172A' } }
  };
  const doubleBarLineBorderRight = {
    right: { style: 'double', color: { argb: 'FF0F172A' } }
  };

  let currentRow = 2;

  // 1. 曲タイトルとメタデータ
  sheet.mergeCells(`B${currentRow}:L${currentRow}`);
  const titleCell = sheet.getCell(`B${currentRow}`);
  titleCell.value = `🎵 ${song.title || '無題のタブ譜'}  -  ${song.artist || 'TabMaker'} (BPM: ${song.bpm || 120} / 拍子: ${song.timeSignature || '4/4'})`;
  titleCell.font = { name: 'Arial', size: 14, bold: true, color: { argb: 'FF0F172A' } };
  titleCell.alignment = { vertical: 'middle' };
  sheet.getRow(currentRow).height = 30;
  currentRow += 2;

  // 各列の幅をコンパクトに設定（1スロット = 1セル、B列からタブスロット開始）
  sheet.getColumn(1).width = 3; // A列：左余白
  for (let c = 2; c <= 80; c++) {
    sheet.getColumn(c).width = 4.2; // タブスロット列（B列から直接スロット配置）
  }

  // 1行に配置する小節数（通常4小節）
  const MEASURES_PER_ROW = 4;

  // 曲全体の標準最大列幅を算出（省略セクションも同じ横幅で揃えるため）
  let songDefaultMaxCols = 33;
  (song.sections || []).forEach(sec => {
    const ms = sec.measures || [];
    for (let mIdx = 0; mIdx < ms.length; mIdx += MEASURES_PER_ROW) {
      const rowMeasures = ms.slice(mIdx, mIdx + MEASURES_PER_ROW);
      let cols = 1;
      rowMeasures.forEach(m => {
        cols += (m.half1Divisions || 4) + (m.half2Divisions || 4);
      });
      if (cols > songDefaultMaxCols) songDefaultMaxCols = cols;
    }
  });

  // 各セクションの出力
  song.sections.forEach(section => {
    const secColorHex = (section.color || '#3b82f6').replace('#', '');
    const secTitle = section.type === 'custom' ? (section.customName || 'カスタム') : section.type;
    const isCompact = Boolean(section.isCompact) || !section.measures || section.measures.length === 0;
    const isChordOnly = Boolean(section.isChordOnly);

    // 小節を4小節ずつチャンクに分割
    const measures = section.measures || [];

    // セクション見出し行の幅計算（最大小節行の列幅に合わせる：B列=2から開始）
    let maxColsInRow = isCompact ? songDefaultMaxCols : 18;
    for (let mIdx = 0; mIdx < measures.length; mIdx += MEASURES_PER_ROW) {
      const rowMeasures = measures.slice(mIdx, mIdx + MEASURES_PER_ROW);
      let cols = 1; // B列が2なので初期値1
      rowMeasures.forEach(m => {
        cols += (m.half1Divisions || 4) + (m.half2Divisions || 4);
      });
      if (cols > maxColsInRow) maxColsInRow = cols;
    }

    // セクション見出し行（譜面幅全体をセクションカラーで塗りつぶし）
    const startSecCol = 2; // B列から開始
    const headerRowIdx = currentRow;
    const endColLetter = sheet.getColumn(maxColsInRow).letter;
    const secFill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF' + secColorHex }
    };

    if (isCompact && section.footerText && section.footerText.trim() !== '') {
      const splitCol = Math.max(startSecCol + 1, Math.floor((startSecCol + maxColsInRow) / 2));
      const splitColLetter = sheet.getColumn(splitCol).letter;
      const rightStartColLetter = sheet.getColumn(splitCol + 1).letter;

      sheet.mergeCells(`B${headerRowIdx}:${splitColLetter}${headerRowIdx}`);
      const secTitleCell = sheet.getCell(`B${headerRowIdx}`);
      secTitleCell.value = `【 ${secTitle} 】`;
      secTitleCell.font = sectionTitleFont;
      secTitleCell.fill = secFill;
      secTitleCell.alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };

      sheet.mergeCells(`${rightStartColLetter}${headerRowIdx}:${endColLetter}${headerRowIdx}`);
      const compactFooterCell = sheet.getCell(`${rightStartColLetter}${headerRowIdx}`);
      compactFooterCell.value = section.footerText;
      compactFooterCell.font = {
        name: 'Arial',
        size: 11,
        bold: true,
        color: { argb: 'FFFFFFFF' }
      };
      compactFooterCell.fill = secFill;
      compactFooterCell.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
    } else {
      sheet.mergeCells(`B${headerRowIdx}:${endColLetter}${headerRowIdx}`);
      const secTitleCell = sheet.getCell(`B${headerRowIdx}`);
      secTitleCell.value = `【 ${secTitle} 】`;
      secTitleCell.font = sectionTitleFont;
      secTitleCell.fill = secFill;
      secTitleCell.alignment = { vertical: 'middle', indent: 1 };
    }
    sheet.getRow(headerRowIdx).height = 24;

    if (isCompact) {
      const secOuterBorder = { style: 'medium', color: { argb: 'FF' + secColorHex } };
      for (let c = startSecCol; c <= maxColsInRow; c++) {
        const cell = sheet.getCell(headerRowIdx, c);
        cell.border = {
          ...(cell.border || {}),
          top: secOuterBorder,
          bottom: secOuterBorder,
          ...(c === startSecCol ? { left: secOuterBorder } : {}),
          ...(c === maxColsInRow ? { right: secOuterBorder } : {})
        };
      }
      currentRow = headerRowIdx + 2;
      return;
    }

    currentRow += 1;

    for (let mIdx = 0; mIdx < measures.length; mIdx += MEASURES_PER_ROW) {
      const rowMeasures = measures.slice(mIdx, mIdx + MEASURES_PER_ROW);

      if (isChordOnly) {
        // コードセクション：コード入力の行のみを出力（4小節 / 1行）
        const chordRowIdx = currentRow;
        sheet.getRow(chordRowIdx).height = 24;

        let currentCol = 2;
        const startSecCol = 2;

        rowMeasures.forEach((measure) => {
          const half1 = measure.half1Divisions || 4;
          const half2 = measure.half2Divisions || 4;
          const totalSlots = half1 + half2;
          const startCol = currentCol;
          const endCol = currentCol + totalSlots - 1;

          let measureFill = null;
          if (measure.color && measure.color !== 'transparent') {
            const mColorHex = measure.color.replace('#', '');
            measureFill = {
              type: 'pattern',
              pattern: 'solid',
              fgColor: { argb: 'FF' + mColorHex }
            };
          }

          if (measure.chords && measure.chords.length > 0) {
            measure.chords.forEach(chord => {
              const relSlot = Math.round((chord.positionPercent / 100) * (totalSlots - 1));
              const chordCol = Math.min(endCol, startCol + relSlot);
              const cCell = sheet.getCell(chordRowIdx, chordCol);
              cCell.value = chord.text;
              cCell.font = chordFont;
              cCell.alignment = { horizontal: 'left', vertical: 'middle' };
            });
          }

          const chordRowBorderLine = { style: 'thin', color: { argb: 'FFCBD5E1' } };
          for (let c = startCol; c <= endCol; c++) {
            const cell = sheet.getCell(chordRowIdx, c);
            const cellBorder = {
              ...(cell.border || {}),
              top: chordRowBorderLine,
              bottom: chordRowBorderLine
            };
            if (c === endCol) {
              cellBorder.right = { style: 'thin', color: { argb: 'FF94A3B8' } };
            }
            cell.border = cellBorder;
            if (measureFill) {
              cell.fill = measureFill;
            }
          }

          currentCol = endCol + 1;
        });

        const endSecCol = currentCol - 1;
        const secBorderMedium = { style: 'medium', color: { argb: 'FF' + secColorHex } };
        const leftCell = sheet.getCell(chordRowIdx, startSecCol);
        leftCell.border = { ...(leftCell.border || {}), left: secBorderMedium };
        const rightCell = sheet.getCell(chordRowIdx, endSecCol);
        rightCell.border = { ...(rightCell.border || {}), right: secBorderMedium };

        currentRow = chordRowIdx + 1;
        continue;
      }

      // 小節の開始行（B列=2から開始、1E〜6Eの弦表示列は不要）
      const chordRowIdx = currentRow;
      const tabStartRowIdx = currentRow + 1; // 弦1〜6行: tabStartRowIdx .. tabStartRowIdx + 5
      const noteRowIdx = tabStartRowIdx + 6; // スタンプ・注記行

      sheet.getRow(chordRowIdx).height = 20;
      for (let s = 0; s < 6; s++) {
        sheet.getRow(tabStartRowIdx + s).height = 18;
      }
      sheet.getRow(noteRowIdx).height = 18;

      let currentCol = 2; // B列から直接第1小節を開始
      const startSecCol = 2;

      rowMeasures.forEach((measure, measureIdxInRow) => {
        const half1 = measure.half1Divisions || 4;
        const half2 = measure.half2Divisions || 4;
        const totalSlots = half1 + half2;
        const startCol = currentCol;
        const endCol = currentCol + totalSlots - 1;

        // 小節の背景色
        let measureFill = null;
        if (measure.color && measure.color !== 'transparent') {
          const mColorHex = measure.color.replace('#', '');
          measureFill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: 'FF' + mColorHex }
          };
        }

        // 小節番号とコードの配置（コード行）
        if (measure.chords && measure.chords.length > 0) {
          measure.chords.forEach(chord => {
            const relSlot = Math.round((chord.positionPercent / 100) * (totalSlots - 1));
            const chordCol = Math.min(endCol, startCol + relSlot);
            const cCell = sheet.getCell(chordRowIdx, chordCol);
            cCell.value = chord.text;
            cCell.font = chordFont;
            cCell.alignment = { horizontal: 'left', vertical: 'middle' };
          });
        }

        // 各弦のタブスロットを描画（1E〜6Eの弦ラベル表示は不要）
        for (let s = 0; s < 6; s++) {
          const r = tabStartRowIdx + s;
          for (let slot = 0; slot < totalSlots; slot++) {
            const c = startCol + slot;
            const cell = sheet.getCell(r, c);

            // 音符・フレット番号
            const fretVal = measure.notes && measure.notes[s] ? measure.notes[s][slot] : undefined;
            if (fretVal !== undefined && fretVal !== '') {
              // 純粋な数値（"0", "1", 12 等）の場合は数値型（Number）でセットし、
              // Excelの「数値がテキストとして保存されています」警告を根本から防止
              if (typeof fretVal === 'number') {
                cell.value = fretVal;
              } else if (typeof fretVal === 'string' && /^\d+$/.test(fretVal.trim())) {
                cell.value = parseInt(fretVal.trim(), 10);
              } else {
                cell.value = fretVal;
              }
            }

            cell.font = tabFont;
            cell.alignment = { horizontal: 'center', vertical: 'middle' };

            // 弦の上下罫線
            const cellBorder = { ...tabLineBorder };
            // 小節末尾の縦線（小節線）
            if (slot === totalSlots - 1) {
              cellBorder.right = (measureIdxInRow === rowMeasures.length - 1 && mIdx + rowMeasures.length === measures.length)
                ? { style: 'double', color: { argb: 'FF0F172A' } }
                : { style: 'medium', color: { argb: 'FF0F172A' } };
            }
            // 前半と後半の境界に点線
            if (slot === half1 - 1) {
              cellBorder.right = { style: 'dotted', color: { argb: 'FF94A3B8' } };
            }
            cell.border = cellBorder;

            if (measureFill) {
              cell.fill = measureFill;
            }
          }
        }

        // スタンプ・注記の出力（エクセルの挿入画像として配置）
        if (measure.stamps && measure.stamps.length > 0) {
          measure.stamps.forEach(stamp => {
            const mWidth = stamp.measureWidth || 320;
            const mHeight = stamp.measureHeight || 180;

            // X位置から正確なスロット列を計算（スタンプ中心位置）
            const stampCenterX = (stamp.x || 0) + (stamp.width || 30) / 2;
            const relX = Math.max(0, Math.min(0.99, stampCenterX / mWidth));
            const targetSlot = Math.min(totalSlots - 1, Math.floor(relX * totalSlots));
            const targetCol = startCol + targetSlot;

            // Y位置から該当弦インデックス（0: 1弦 〜 5: 6弦）を計算
            const stampCenterY = (stamp.y || 0) + (stamp.height || 20) / 2;
            const strHeight = mHeight / 6;
            const targetStrIdx = Math.max(0, Math.min(5, Math.floor(stampCenterY / strHeight)));
            const targetRow = tabStartRowIdx + targetStrIdx;

            // 1. エクセル挿入画像として貼り付け
            const imgInfo = renderStampToPng(stamp);
            if (imgInfo && imgInfo.base64) {
              const imageId = workbook.addImage({
                base64: imgInfo.base64,
                extension: 'png'
              });

              // 中心位置から小数点のセル座標を計算
              const progressX = Math.max(0, Math.min(1.0, stampCenterX / mWidth));
              const centerColFloat = startCol + progressX * totalSlots;
              const halfWidthCols = (imgInfo.width / 2) / 35; // 1列幅 ≈ 35px
              const targetColFloat = Math.max(startCol, centerColFloat - halfWidthCols);

              const progressY = Math.max(0, Math.min(1.0, stampCenterY / mHeight));
              const centerRowFloat = tabStartRowIdx + progressY * 6;
              const halfHeightRows = (imgInfo.height / 2) / 24; // 1行高さ ≈ 24px
              const targetRowFloat = Math.max(chordRowIdx, centerRowFloat - halfHeightRows);

              sheet.addImage(imageId, {
                tl: { col: targetColFloat, row: targetRowFloat },
                ext: { width: imgInfo.width, height: imgInfo.height },
                editAs: 'oneCell'
              });
            }

            // 2. チョーキングのフレット数字への合成（例: '7c'）
            if (stamp.type === 'choke') {
              const tabCell = sheet.getCell(targetRow, targetCol);
              if (tabCell.value !== undefined && tabCell.value !== null && tabCell.value !== '') {
                const sVal = String(tabCell.value);
                if (!sVal.includes('c')) {
                  tabCell.value = sVal + 'c';
                }
              }
            }
          });
        }

        currentCol = endCol + 1;
      });

      const endSecCol = currentCol - 1;

      // 段落内のコード行(chordRowIdx)から注記行(noteRowIdx)の上下左右仕切り線
      const secBorderMedium = { style: 'medium', color: { argb: 'FF' + secColorHex } };

      for (let c = startSecCol; c <= endSecCol; c++) {
        const topCell = sheet.getCell(chordRowIdx, c);
        topCell.border = { ...(topCell.border || {}), top: secBorderMedium };

        const bottomCell = sheet.getCell(noteRowIdx, c);
        bottomCell.border = { ...(bottomCell.border || {}), bottom: secBorderMedium };
      }

      for (let r = chordRowIdx; r <= noteRowIdx; r++) {
        const leftCell = sheet.getCell(r, startSecCol);
        leftCell.border = { ...(leftCell.border || {}), left: secBorderMedium };

        const rightCell = sheet.getCell(r, endSecCol);
        rightCell.border = { ...(rightCell.border || {}), right: secBorderMedium };
      }

      if (mIdx + MEASURES_PER_ROW < measures.length) {
        currentRow = noteRowIdx + 2; // 次の行グループへ（1行空行）
      } else {
        currentRow = noteRowIdx + 1; // 最終行グループの直後にフッター行を配置
      }
    }

    // セクション末尾のカラー付き行（ヘッダーと同じ高さ、同じカラー、右寄せ白抜きテキスト）
    const footerRowIdx = currentRow;
    sheet.mergeCells(`B${footerRowIdx}:${endColLetter}${footerRowIdx}`);
    const secFooterCell = sheet.getCell(`B${footerRowIdx}`);
    secFooterCell.value = section.footerText || '';
    secFooterCell.font = {
      name: 'Arial',
      size: 11,
      bold: true,
      color: { argb: 'FFFFFFFF' }
    };
    secFooterCell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF' + secColorHex }
    };
    secFooterCell.alignment = { horizontal: 'right', vertical: 'middle', indent: 1 };
    sheet.getRow(footerRowIdx).height = 24; // ヘッダーと同じ高さ

    // 【セクション全体を指定カラーで囲む】
    // ヘッダー行(headerRowIdx)からフッター行(footerRowIdx)までの全外枠を指定カラー太線で囲む
    const secOuterBorder = { style: 'medium', color: { argb: 'FF' + secColorHex } };

    // 1. 最上端（ヘッダー上）
    for (let c = startSecCol; c <= maxColsInRow; c++) {
      const cell = sheet.getCell(headerRowIdx, c);
      cell.border = { ...(cell.border || {}), top: secOuterBorder };
    }

    // 2. 最下端（フッター下）
    for (let c = startSecCol; c <= maxColsInRow; c++) {
      const cell = sheet.getCell(footerRowIdx, c);
      cell.border = { ...(cell.border || {}), bottom: secOuterBorder };
    }

    // 3. 左端（ヘッダー〜フッター全行のB列左）
    // 4. 右端（ヘッダー〜フッター全行の末尾列右）
    for (let r = headerRowIdx; r <= footerRowIdx; r++) {
      const leftCell = sheet.getCell(r, startSecCol);
      leftCell.border = { ...(leftCell.border || {}), left: secOuterBorder };

      const rightCell = sheet.getCell(r, maxColsInRow);
      rightCell.border = { ...(rightCell.border || {}), right: secOuterBorder };
    }

    // 5. ヘッダー下端・フッター上端の仕切り線
    for (let c = startSecCol; c <= maxColsInRow; c++) {
      const headerCell = sheet.getCell(headerRowIdx, c);
      headerCell.border = { ...(headerCell.border || {}), bottom: secOuterBorder };

      const footerCell = sheet.getCell(footerRowIdx, c);
      footerCell.border = { ...(footerCell.border || {}), top: secOuterBorder };
    }

    currentRow = footerRowIdx + 2; // フッター行の後にセクション間スペース
  });

  return workbook;
}

/**
 * ワークシートXMLに ignoredErrors を注入し、テキストや記号があるセルに表示される
 * Excelのエラーインジケーター（緑の三角マーク）をすべて無視・非表示にする
 */
async function injectIgnoredErrorsIntoWorkbookBuffer(buffer) {
  try {
    const zip = await JSZip.loadAsync(buffer);
    // OpenXML仕様に基づき、シート全体のテキスト数値警告や評価エラー等を無視するタグ
    const ignoredErrorsXml = '<ignoredErrors><ignoredError sqref="A1:XFD1048576" evalError="1" twoDigitTextYear="1" numberStoredAsText="1" formula="1" calculatedColumn="1" emptyCellReference="1"/></ignoredErrors>';

    // OpenXMLスキーマ順序: cellWatchesの直後、drawing/drawingHF/picture/tableParts/extLst/</worksheet>の直前に挿入
    const targetRegex = /(<drawing[ >]|<drawingHF[ >]|<picture[ >]|<oleObjects[ >]|<controls[ >]|<webPublishItems[ >]|<tableParts[ >]|<extLst[ >]|<\/worksheet>)/;

    let modified = false;
    for (const filename of Object.keys(zip.files)) {
      if (filename.startsWith('xl/worksheets/sheet') && filename.endsWith('.xml')) {
        let sheetXml = await zip.file(filename).async('string');
        if (!sheetXml.includes('<ignoredErrors>')) {
          if (targetRegex.test(sheetXml)) {
            sheetXml = sheetXml.replace(targetRegex, (match) => `${ignoredErrorsXml}${match}`);
            zip.file(filename, sheetXml);
            modified = true;
          }
        }
      }
    }

    if (modified) {
      return await zip.generateAsync({ type: 'arraybuffer' });
    }
  } catch (err) {
    console.warn('ignoredErrorsの注入中に警告が発生しました:', err);
  }
  return buffer;
}

export async function exportToGoogleSheetsExcel(song, options = {}) {
  const workbook = buildExcelWorkbook(song);

  // バッファを生成
  let buffer = await workbook.xlsx.writeBuffer();
  // テキストセルに表示されるエラー（緑の三角マーク）を無視する設定を注入
  buffer = await injectIgnoredErrorsIntoWorkbookBuffer(buffer);

  const safeTitle = (song.title || 'TabMaker').replace(/[/\\?%*:|"<>]/g, '_');
  const filename = `${safeTitle}_Googleスプレッドシート共有用.xlsx`;

  const blob = new Blob([buffer], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  });

  let savedLocalPath = null;
  let outputDirectory = null;

  // ArrayBufferからBase64へ安全に変換するヘルパー
  const arrayBufferToBase64 = (buf) => {
    let binary = '';
    const bytes = new Uint8Array(buf);
    const len = bytes.byteLength;
    const chunkSize = 8192;
    for (let i = 0; i < len; i += chunkSize) {
      binary += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(i + chunkSize, len)));
    }
    return btoa(binary);
  };

  // --- Androidアプリ環境の場合の書き出し処理 ---
  if (isAndroidApp()) {
    try {
      const base64Data = arrayBufferToBase64(buffer);

      // 端末の「Documents/TabMaker」フォルダに保存（ユーザーがファイル管理アプリから直接閲覧可能）
      const writeResult = await Filesystem.writeFile({
        path: `TabMaker/${filename}`,
        data: base64Data,
        directory: Directory.Documents,
        recursive: true
      });

      savedLocalPath = writeResult.uri;
      outputDirectory = '内部ストレージ > Documents > TabMaker';

      const androidSettings = getAndroidExportSettings();
      let shared = false;
      // 自動共有が有効な場合、共有ダイアログを起動（Googleドライブ・スプレッドシート・LINE等）
      if (androidSettings.autoShare && !options.skipAutoShare) {
        try {
          await Share.share({
            title: filename,
            text: `TabMakerタブ譜: ${song.title || '無題'}`,
            url: writeResult.uri,
            dialogTitle: 'スプレッドシート用ファイルの共有・保存'
          });
          shared = true;
        } catch (shareErr) {
          console.log('共有ダイアログのキャンセル:', shareErr);
        }
      }

      return {
        success: true,
        filename: filename,
        filePath: savedLocalPath,
        outputDir: outputDirectory,
        fileUri: writeResult.uri,
        isAndroid: true,
        shared: shared
      };
    } catch (fsErr) {
      console.warn('Documents保存エラー、Cacheへフォールバック:', fsErr);
      try {
        const base64Data = arrayBufferToBase64(buffer);
        const cacheResult = await Filesystem.writeFile({
          path: filename,
          data: base64Data,
          directory: Directory.Cache
        });

        await Share.share({
          title: filename,
          text: `TabMakerタブ譜: ${song.title || '無題'}`,
          url: cacheResult.uri,
          dialogTitle: 'スプレッドシート用ファイルの共有・保存'
        });

        return {
          success: true,
          filename: filename,
          filePath: cacheResult.uri,
          outputDir: '一時保存領域 (Cache)',
          fileUri: cacheResult.uri,
          isAndroid: true,
          shared: true
        };
      } catch (cacheErr) {
        console.error('端末ファイル保存・共有失敗:', cacheErr);
        throw new Error('端末へのファイル保存に失敗しました: ' + (fsErr.message || ''));
      }
    }
  }

  // --- PC / ブラウザ環境の場合の書き出し処理 ---
  // 1. ローカルサーバーのAPI経由で設定済みフォルダに直接保存
  try {
    const base64Data = arrayBufferToBase64(buffer);

    const res = await fetch('/api/save-excel', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ filename, base64Data, targetDir: options.targetDir })
    });
    if (res.ok) {
      const data = await res.json();
      savedLocalPath = data.filePath;
      outputDirectory = data.outputDir;
    }
  } catch (e) {
    console.warn('ローカルサーバーへの直接保存はスキップされました:', e);
  }

  // 2. ブラウザ標準のダウンロード（Blob URL + a.download）
  const url = URL.createObjectURL(blob);
  if (!options.skipBrowserDownload) {
    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();

    setTimeout(() => {
      if (a.parentNode) {
        document.body.removeChild(a);
      }
      URL.revokeObjectURL(url);
    }, 60000);
  }

  return {
    success: true,
    filename: filename,
    filePath: savedLocalPath,
    outputDir: outputDirectory,
    blobUrl: url,
    isAndroid: false
  };
}

/**
 * Androidでエクスポートされたファイルを共有シートで開く
 */
export async function shareExportedFile(fileUri, filename, title = '') {
  if (isAndroidApp() && fileUri) {
    try {
      await Share.share({
        title: filename || 'TabMaker_Googleスプレッドシート共有用.xlsx',
        text: `TabMakerタブ譜: ${title || 'タブ譜'}`,
        url: fileUri,
        dialogTitle: 'スプレッドシート用ファイルの共有・保存'
      });
      return true;
    } catch (e) {
      console.log('共有キャンセルまたはエラー:', e);
      return false;
    }
  }
  return false;
}

/**
 * フォルダ参照（Windows標準ダイアログを起動して保存先フォルダを選択）
 */
export async function selectExportFolder() {
  if (isAndroidApp()) {
    return { cancelled: true, message: 'Androidでは内部ストレージのDocuments/TabMakerに保存されます' };
  }

  try {
    const res = await fetch('/api/select-folder', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' }
    });
    if (res.ok) {
      const data = await res.json();
      return data;
    }
  } catch (e) {
    console.error('サーバーフォルダ選択エラー:', e);
  }

  return { cancelled: true };
}

/**
 * 手動でフォルダパスを設定
 */
export async function setExportFolder(outputDir) {
  if (isAndroidApp()) {
    return { success: true, outputDir: '内部ストレージ > Documents > TabMaker' };
  }

  try {
    const res = await fetch('/api/set-settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ outputDir })
    });
    if (res.ok) {
      return await res.json();
    }
  } catch (e) {
    console.error('設定更新エラー:', e);
  }
  return { error: '設定更新に失敗しました' };
}

/**
 * 現在の保存先設定を取得
 */
export async function getExportSettings() {
  if (isAndroidApp()) {
    const androidSettings = getAndroidExportSettings();
    return {
      isAndroid: true,
      outputDir: '内部ストレージ > Documents > TabMaker',
      displayName: 'Documents/TabMaker',
      presetDirs: {
        documents: '内部ストレージ > Documents > TabMaker'
      },
      androidSettings
    };
  }

  try {
    const res = await fetch('/api/get-settings');
    if (res.ok) {
      return await res.json();
    }
  } catch (e) {
    console.error('設定取得エラー:', e);
  }
  return { outputDir: 'output' };
}

/**
 * 保存先フォルダまたはファイルをWindowsエクスプローラーで開く
 */
export async function openExportFolder(filePath = null) {
  if (isAndroidApp()) {
    return false;
  }

  try {
    const res = await fetch('/api/open-folder', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ filePath })
    });
    return res.ok;
  } catch (e) {
    console.error('フォルダを開けませんでした:', e);
    return false;
  }
}

