/**
 * セクションビュー (SectionView)
 * 仕様：
 * - セクション単位で外枠で囲む
 * - 以下のタイプをリスト選択できる：
 *   - aメロ, bメロ, cメロ, 展開, SOLO, INTRO, OUTRO, 間奏, サビ, カスタム自由入力
 * - セクションごとにカラーを変えられる
 */
import { SECTION_TYPES, createNewMeasure } from '../models/types.js';
import { MeasureView } from './MeasureView.js';

export class SectionView {
  constructor(app, section) {
    this.app = app;
    this.section = section;
  }

  render() {
    const s = this.section;
    const isCompact = Boolean(s.isCompact);
    const isChordOnly = Boolean(s.isChordOnly);
    const container = document.createElement('div');
    container.className = 'section-container';
    if (isCompact) {
      container.classList.add('section-compact');
    }
    if (isChordOnly) {
      container.classList.add('section-chord-only');
    }
    if (this.app.activeSectionId === s.id) {
      container.classList.add('is-active-section');
    }
    container.id = `section-${s.id}`;
    container.dataset.sectionId = s.id;

    // クリックやフォーカスでこのセクションをアクティブにする
    container.addEventListener('pointerdown', () => {
      this.app.setActiveSection(s.id);
    });
    container.addEventListener('focusin', () => {
      this.app.setActiveSection(s.id);
    });

    const secColor = s.color || '#3b82f6';
    container.style.borderColor = secColor;
    container.style.borderWidth = '3px';
    container.style.borderStyle = 'solid';
    container.style.borderLeft = `8px solid ${secColor}`;
    container.style.boxShadow = `0 4px 18px ${secColor}26`;

    // セクションドラッグ＆ドロップ受け入れ対応（ドロップ先としての設定）
    container.addEventListener('dragover', (e) => {
      // 小節ドラッグまたはスタンプドラッグの時はセクション入れ替えは行わない
      const types = e.dataTransfer.types;
      if (types.includes('application/tabmaker-stamp')) return;

      // セクションドラッグ中のみ反応
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';

      const rect = container.getBoundingClientRect();
      const midY = rect.top + rect.height / 2;
      if (e.clientY < midY) {
        container.classList.add('drag-over-top');
        container.classList.remove('drag-over-bottom');
      } else {
        container.classList.add('drag-over-bottom');
        container.classList.remove('drag-over-top');
      }
    });

    container.addEventListener('dragleave', (e) => {
      // コンテナ外に出た時のみ解除
      if (!container.contains(e.relatedTarget)) {
        container.classList.remove('drag-over-top', 'drag-over-bottom');
      }
    });

    container.addEventListener('drop', (e) => {
      container.classList.remove('drag-over-top', 'drag-over-bottom');
      try {
        const raw = e.dataTransfer.getData('text/plain');
        if (!raw) return;
        const data = JSON.parse(raw);
        if (data && data.type === 'tabmaker-section') {
          e.preventDefault();
          e.stopPropagation();
          if (data.sourceSecId === s.id) return; // 同一セクションへのドロップは何もしない
          const rect = container.getBoundingClientRect();
          const placeBefore = e.clientY < (rect.top + rect.height / 2);
          this.app.moveSection(data.sourceSecId, s.id, placeBefore);
        }
      } catch (err) {
        // 無視
      }
    });

    // 1. セクションヘッダー（セクションカラーで帯状に塗りつぶし）
    const header = document.createElement('div');
    header.className = 'section-header';
    header.style.backgroundColor = secColor;
    header.style.borderBottom = isCompact ? 'none' : `2px solid ${secColor}`;
    header.style.color = '#ffffff';

    // 左側：ドラッグハンドル & セクションタイプ選択ドロップダウン & カスタム入力
    const leftBox = document.createElement('div');
    leftBox.className = 'section-header-left';

    // セクション移動は左上のマークでのみ行う
    const dragHandle = document.createElement('span');
    dragHandle.className = 'section-drag-handle';
    dragHandle.innerHTML = '⠿';
    dragHandle.title = 'ドラッグしてセクションの順番を並べ替え';
    dragHandle.setAttribute('draggable', 'true');

    dragHandle.addEventListener('dragstart', (e) => {
      e.stopPropagation();
      e.dataTransfer.setData('text/plain', JSON.stringify({
        type: 'tabmaker-section',
        sourceSecId: s.id
      }));
      e.dataTransfer.effectAllowed = 'move';
      container.classList.add('is-dragging-section');

      if (e.dataTransfer.setDragImage) {
        const rect = container.getBoundingClientRect();
        e.dataTransfer.setDragImage(container, e.clientX - rect.left, e.clientY - rect.top);
      }
    });

    dragHandle.addEventListener('dragend', () => {
      container.classList.remove('is-dragging-section');
      document.querySelectorAll('.section-container').forEach(c => {
        c.classList.remove('drag-over-top', 'drag-over-bottom');
      });
    });

    // --- タッチ・ポインターによるセクションドラッグ操作（Android / モバイル対応） ---
    let secTouchDragging = false;
    let secFloatingPreview = null;
    let currentSecDropTarget = null;

    const secName = s.type === 'custom' ? (s.customName || 'カスタム') : s.type;

    const updateSecPreviewPos = (x, y) => {
      if (secFloatingPreview) {
        secFloatingPreview.style.left = `${x}px`;
        secFloatingPreview.style.top = `${y}px`;
      }
    };

    const checkSecDropTarget = (clientX, clientY) => {
      document.querySelectorAll('.section-container').forEach(c => {
        c.classList.remove('drag-over-top', 'drag-over-bottom');
      });

      const el = document.elementFromPoint(clientX, clientY);
      if (!el) {
        currentSecDropTarget = null;
        return;
      }

      const targetSec = el.closest('.section-container');
      if (targetSec && targetSec.dataset.sectionId && targetSec.dataset.sectionId !== s.id) {
        const rect = targetSec.getBoundingClientRect();
        const placeBefore = clientY < (rect.top + rect.height / 2);
        targetSec.classList.add(placeBefore ? 'drag-over-top' : 'drag-over-bottom');
        currentSecDropTarget = {
          targetSecId: targetSec.dataset.sectionId,
          placeBefore: placeBefore
        };
      } else {
        currentSecDropTarget = null;
      }
    };

    const onSecPointerMove = (e) => {
      if (!secTouchDragging) return;
      if (e.cancelable) e.preventDefault();
      updateSecPreviewPos(e.clientX, e.clientY);
      checkSecDropTarget(e.clientX, e.clientY);
    };

    const onSecTouchMove = (e) => {
      if (!secTouchDragging) return;
      if (e.cancelable) e.preventDefault();
      const touch = e.touches[0];
      if (touch) {
        updateSecPreviewPos(touch.clientX, touch.clientY);
        checkSecDropTarget(touch.clientX, touch.clientY);
      }
    };

    const removeAllSecPreviews = () => {
      document.querySelectorAll('.drag-floating-preview').forEach(el => el.remove());
      secFloatingPreview = null;
    };

    const onSecPointerUp = () => {
      if (!secTouchDragging) {
        removeAllSecPreviews();
        return;
      }
      secTouchDragging = false;

      window.removeEventListener('pointermove', onSecPointerMove);
      window.removeEventListener('pointerup', onSecPointerUp);
      window.removeEventListener('pointercancel', onSecPointerUp);
      window.removeEventListener('touchmove', onSecTouchMove);
      window.removeEventListener('touchend', onSecPointerUp);

      removeAllSecPreviews();

      container.classList.remove('is-dragging-section');
      document.querySelectorAll('.section-container').forEach(c => {
        c.classList.remove('drag-over-top', 'drag-over-bottom');
      });

      if (currentSecDropTarget) {
        const { targetSecId, placeBefore } = currentSecDropTarget;
        this.app.moveSection(s.id, targetSecId, placeBefore);
        currentSecDropTarget = null;
      }
    };

    const onSecPointerDown = (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      e.stopPropagation();

      // 他の画面上に残存するプレビューを一括消去
      removeAllSecPreviews();

      secTouchDragging = true;
      currentSecDropTarget = null;
      container.classList.add('is-dragging-section');

      secFloatingPreview = document.createElement('div');
      secFloatingPreview.className = 'drag-floating-preview';
      secFloatingPreview.innerHTML = `<span>⠿ セクション「${secName}」を移動中</span>`;
      document.body.appendChild(secFloatingPreview);

      const clientX = e.clientX ?? (e.touches && e.touches[0] ? e.touches[0].clientX : 0);
      const clientY = e.clientY ?? (e.touches && e.touches[0] ? e.touches[0].clientY : 0);
      updateSecPreviewPos(clientX, clientY);

      window.addEventListener('pointermove', onSecPointerMove, { passive: false });
      window.addEventListener('pointerup', onSecPointerUp);
      window.addEventListener('pointercancel', onSecPointerUp);
      window.addEventListener('touchmove', onSecTouchMove, { passive: false });
      window.addEventListener('touchend', onSecPointerUp);
    };

    dragHandle.addEventListener('pointerdown', onSecPointerDown);

    leftBox.appendChild(dragHandle);

    if (s.type === 'custom') {
      // 「カスタム自由入力」の場合：ドロップダウンの文字そのものを直接上書きできる入力バッジ
      const customBadgeGroup = document.createElement('div');
      customBadgeGroup.className = 'section-custom-badge-group';

      const customInput = document.createElement('input');
      customInput.type = 'text';
      customInput.className = 'section-custom-input-main';
      customInput.placeholder = 'セクション名入力';
      customInput.value = s.customName || '';
      customInput.title = 'セクション名を直接編集（上書き可能）';

      customInput.addEventListener('input', (e) => {
        s.customName = e.target.value;
        this.app.saveState();
        this.app.updatePlayBtnText();
      });
      customInput.addEventListener('change', () => {
        this.app.pushHistory();
      });

      // 種別変更用ドロップダウン（右端の▼アイコンをクリックしていつでもプリセットに戻せる）
      const switcherWrap = document.createElement('div');
      switcherWrap.className = 'section-type-switcher-wrap';
      switcherWrap.title = 'セクション種別を変更';

      const switcherIcon = document.createElement('span');
      switcherIcon.className = 'section-type-switcher-icon';
      switcherIcon.textContent = '▼';

      const typeSelect = document.createElement('select');
      typeSelect.className = 'section-type-switcher-select';
      typeSelect.title = 'セクション種別を変更';

      SECTION_TYPES.forEach(type => {
        const opt = document.createElement('option');
        opt.value = type.id;
        opt.textContent = type.label;
        if (type.id === 'custom') {
          opt.selected = true;
          opt.textContent = '✏️ カスタム自由入力';
        }
        typeSelect.appendChild(opt);
      });

      typeSelect.addEventListener('change', (e) => {
        const prevMeta = SECTION_TYPES.find(t => t.id === s.type);
        s.type = e.target.value;
        const matched = SECTION_TYPES.find(t => t.id === s.type);
        if (matched && (!s.color || (prevMeta && s.color === prevMeta.defaultColor))) {
          s.color = matched.defaultColor;
        }
        this.app.saveStateAndRender();
      });

      switcherWrap.appendChild(switcherIcon);
      switcherWrap.appendChild(typeSelect);

      customBadgeGroup.appendChild(customInput);
      customBadgeGroup.appendChild(switcherWrap);
      leftBox.appendChild(customBadgeGroup);

      // カスタム名が未入力の場合は自動でフォーカス
      if (!s.customName) {
        setTimeout(() => {
          customInput.focus();
        }, 50);
      }
    } else {
      // 通常のセクション種別セレクトボックス
      const select = document.createElement('select');
      select.className = 'section-badge-select';
      select.style.backgroundColor = '#ffffff';
      select.style.color = '#0f172a';
      select.style.fontWeight = '800';

      SECTION_TYPES.forEach(type => {
        const opt = document.createElement('option');
        opt.value = type.id;
        opt.textContent = type.label;
        if (s.type === type.id) opt.selected = true;
        select.appendChild(opt);
      });

      select.addEventListener('change', (e) => {
        const prevMeta = SECTION_TYPES.find(t => t.id === s.type);
        s.type = e.target.value;
        const matched = SECTION_TYPES.find(t => t.id === s.type);
        if (matched && (!s.color || (prevMeta && s.color === prevMeta.defaultColor))) {
          s.color = matched.defaultColor;
        }
        this.app.saveStateAndRender();
      });
      leftBox.appendChild(select);
    }

    header.appendChild(leftBox);

    // 右側：個別再生、小節追加、小節貼付、セクション複製、カラー変更、セクション削除
    const rightBox = document.createElement('div');
    rightBox.className = 'section-header-right';

    if (!isCompact) {
      // ▶ / ■ このセクションの再生 / 停止ボタン
      const playSecBtn = document.createElement('button');
      const isCurrentlyPlaying = this.app.currentPlayingSectionId === s.id && this.app.playbackEngine.isPlaying;
      playSecBtn.className = `btn btn-icon-only section-action-btn section-play-btn${isCurrentlyPlaying ? ' playing' : ''}`;
      playSecBtn.dataset.sectionId = s.id;
      playSecBtn.innerHTML = isCurrentlyPlaying ? '■' : '▶';
      playSecBtn.title = isCurrentlyPlaying ? '再生を停止' : 'このセクションを再生';
      playSecBtn.setAttribute('aria-label', isCurrentlyPlaying ? '停止' : '再生');

      let lastPlayTrigger = 0;
      const handleTogglePlay = (e) => {
        e.stopPropagation();
        const now = Date.now();
        if (now - lastPlayTrigger < 250) return; // 二重発火防止
        lastPlayTrigger = now;
        if (e && e.cancelable && e.type !== 'click') {
          e.preventDefault();
        }

        if (this.app.currentPlayingSectionId === s.id && this.app.playbackEngine.isPlaying) {
          this.app.stopPlayback();
        } else {
          this.app.playSection(s.id);
        }
      };
      playSecBtn.addEventListener('click', handleTogglePlay);
      playSecBtn.addEventListener('touchend', handleTogglePlay, { passive: false });
      rightBox.appendChild(playSecBtn);
    }

    // セクションカラー変更ボタン（元の色指定選択パレットを開く）
    const colorBtn = document.createElement('button');
    colorBtn.className = 'section-color-btn';
    colorBtn.style.backgroundColor = secColor;
    colorBtn.style.border = '2px solid #ffffff';
    colorBtn.style.boxShadow = '0 1px 4px rgba(0,0,0,0.3)';
    colorBtn.title = 'セクションのカラーを変更（元の色指定選択）';
    colorBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.app.showColorPicker(colorBtn, (newColor) => {
        s.color = newColor;
        this.app.saveStateAndRender();
      }, 'section');
    });
    rightBox.appendChild(colorBtn);

    if (isCompact) {
      // 省略セクションのバー内：カラーボタンと削除ボタンの間に通常セクション同様の末尾テキスト入力を配置
      const compactFooterInput = document.createElement('input');
      compactFooterInput.type = 'text';
      compactFooterInput.className = 'section-footer-input section-compact-footer-input';
      compactFooterInput.placeholder = 'セクション末尾テキスト（右寄せ）';
      compactFooterInput.value = s.footerText || '';
      compactFooterInput.title = 'セクション末尾のテキスト（右寄せ）';

      compactFooterInput.addEventListener('input', (e) => {
        s.footerText = e.target.value;
        this.app.saveState();
      });
      compactFooterInput.addEventListener('change', () => {
        this.app.pushHistory();
      });

      rightBox.appendChild(compactFooterInput);
    } else {
      // ＋ 小節追加ボタン
      const addMeasureBtn = document.createElement('button');
      addMeasureBtn.className = 'btn btn-secondary btn-sm add-measure-btn';
      addMeasureBtn.innerHTML = '＋ 小節追加';
      addMeasureBtn.style.backgroundColor = '#ffffff';
      addMeasureBtn.style.color = '#0f172a';
      addMeasureBtn.style.fontWeight = '700';
      addMeasureBtn.style.border = 'none';
      addMeasureBtn.title = 'このセクションに新しい小節を追加';
      addMeasureBtn.addEventListener('click', () => {
        const currentCount = s.measures.length;
        const newM = createNewMeasure(currentCount + 1);
        s.measures.push(newM);
        this.app.renumberMeasures();
        this.app.saveStateAndRender();
      });
      rightBox.appendChild(addMeasureBtn);

      // 📥 小節貼付ボタン（このセクション末尾に貼り付け）
      const pasteMeasureBtn = document.createElement('button');
      pasteMeasureBtn.className = `btn btn-secondary btn-sm ${this.app.clipboardMeasure ? 'has-clipboard' : ''}`;
      pasteMeasureBtn.innerHTML = '📥 小節貼付';
      pasteMeasureBtn.style.backgroundColor = this.app.clipboardMeasure ? '#fef08a' : '#f1f5f9';
      pasteMeasureBtn.style.color = '#0f172a';
      pasteMeasureBtn.style.fontWeight = '700';
      pasteMeasureBtn.style.border = 'none';
      pasteMeasureBtn.title = this.app.clipboardMeasure
        ? 'コピーした小節をこのセクションの末尾に貼り付け'
        : '小節をコピーするとここに貼り付けできます';
      pasteMeasureBtn.addEventListener('click', () => {
        this.app.pasteMeasure(s.id, null);
      });
      rightBox.appendChild(pasteMeasureBtn);

      // 📋 セクション複製ボタン（コピー元のセクションのすぐ後に置かれる）
      const cloneBtn = document.createElement('button');
      cloneBtn.className = 'btn btn-icon-only section-action-btn';
      cloneBtn.innerHTML = '📋';
      cloneBtn.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
      cloneBtn.style.border = '1px solid rgba(255, 255, 255, 0.4)';
      cloneBtn.style.color = '#ffffff';
      cloneBtn.title = 'セクションを複製（このセクションのすぐ後ろに配置）';
      cloneBtn.addEventListener('click', () => {
        this.app.duplicateSection(s.id);
      });
      rightBox.appendChild(cloneBtn);
    }

    // セクション削除ボタン
    const delBtn = document.createElement('button');
    delBtn.className = 'btn btn-icon-only section-action-btn';
    delBtn.innerHTML = '🗑️';
    delBtn.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
    delBtn.style.border = '1px solid rgba(255, 255, 255, 0.4)';
    delBtn.style.color = '#ffffff';
    delBtn.title = 'セクションを削除';
    delBtn.addEventListener('click', () => {
      if (confirm(`セクション「${s.type === 'custom' ? (s.customName || 'カスタム') : s.type}」を削除しますか？`)) {
        this.app.deleteSection(s.id);
      }
    });
    rightBox.appendChild(delBtn);

    header.appendChild(rightBox);
    container.appendChild(header);

    // 省略セクションの場合はヘッダーバーのみを表示して返す
    if (isCompact) {
      return container;
    }

    // 2. 小節グリッド
    const grid = document.createElement('div');
    grid.className = 'measures-grid';
    grid.style.borderTop = `1px solid ${secColor}40`;

    (s.measures || []).forEach(measure => {
      const measureView = new MeasureView(this.app, measure, s);
      grid.appendChild(measureView.render());
    });

    container.appendChild(grid);

    // 3. セクション末尾のカラー付き行（ヘッダーと同じ高さ、同じカラー、右寄せ白抜きテキスト入力欄）
    const footer = document.createElement('div');
    footer.className = 'section-footer';
    footer.style.backgroundColor = secColor;
    footer.style.color = '#ffffff';

    const footerInput = document.createElement('input');
    footerInput.type = 'text';
    footerInput.className = 'section-footer-input';
    footerInput.placeholder = 'セクション末尾テキスト（右寄せ）';
    footerInput.value = s.footerText || '';
    footerInput.title = 'セクション末尾のテキスト（右寄せ）';

    footerInput.addEventListener('input', (e) => {
      s.footerText = e.target.value;
      this.app.saveState();
    });
    footerInput.addEventListener('change', () => {
      this.app.pushHistory();
    });

    footer.appendChild(footerInput);
    container.appendChild(footer);

    return container;
  }
}
