// ID生成ヘルパー
export function generateId(prefix = 'id') {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
}

// 新規小節オブジェクトを作成
export function createNewMeasure(measureNumber = 1, options = {}) {
  return {
    id: generateId('meas'),
    number: measureNumber,
    color: options.color || 'transparent',
    half1Divisions: options.half1Divisions || 4, // 最小1, 最大16, デフォルト4
    half2Divisions: options.half2Divisions || 4, // 最小1, 最大16, デフォルト4
    // notes: { [stringIndex (0..5)]: { [slotIndex]: 'フレット文字' } }
    notes: { 0: {}, 1: {}, 2: {}, 3: {}, 4: {}, 5: {} },
    // chords: [ { id, text, positionPercent (0-100) } ]
    chords: options.chords || [],
    // stamps: [ { id, type, x, y, width, height, rotation, color, text } ]
    stamps: options.stamps || []
  };
}

// 新規セクションオブジェクトを作成
export function createNewSection(type = 'INTRO', options = {}) {
  const sectionMeta = SECTION_TYPES.find(s => s.id === type) || SECTION_TYPES[0];
  const isCompact = Boolean(options.isCompact);
  const isChordOnly = Boolean(options.isChordOnly);
  const initialMeasureCount = isCompact ? 0 : (options.measureCount ?? 4);
  const measures = [];
  for (let i = 0; i < initialMeasureCount; i++) {
    measures.push(createNewMeasure(i + 1));
  }

  return {
    id: generateId('sec'),
    type: type,
    customName: options.customName || (type === 'custom' ? '新しいセクション' : ''),
    color: options.color || sectionMeta.defaultColor,
    footerText: options.footerText || '',
    isCompact: isCompact,
    isChordOnly: isChordOnly,
    measures: measures
  };
}

// 新規楽曲オブジェクトを作成
export function createNewSong(title = '新しいタブ譜', artist = 'アーティスト名') {
  return {
    id: generateId('song'),
    title: title,
    artist: artist,
    bpm: 120,
    timeSignature: '4/4',
    capo: 0,
    sections: [
      createNewSection('INTRO', { measureCount: 4 }),
      createNewSection('aメロ', { measureCount: 4 }),
      createNewSection('サビ', { measureCount: 4 })
    ]
  };
}
